/**
 * Policy Clause Templates — Monitoring & Detection (p26-p29)
 * Based on ISO 27001:2022, BSI IT-Grundschutz, NIST CSF 2.0, NIS2 Art.21
 */
import type { PolicyClause } from "../policyClauseTemplates";

export const monitoringDetectionClauses: Record<string, PolicyClause[]> = {

  // ═══════════════════════════════════════════════════════════════
  // P26 — Monitoring & Detection Policy
  // ═══════════════════════════════════════════════════════════════
  p26: [
    { id: "p26-c00", title: "Geltungsbereich und Ziele der Sicherheitsüberwachung", titleEn: "Scope & Objectives of Security Monitoring",
      description: "Wir müssen den Geltungsbereich der Sicherheitsüberwachung klar definieren. Alle geschäftskritischen Systeme, Netzwerke, Anwendungen und Datenverarbeitungsprozesse müssen in die Überwachung einbezogen werden. Die Ziele umfassen die Erkennung von Sicherheitsvorfällen, die Identifizierung von Anomalien, die Unterstützung forensischer Analysen und die Einhaltung regulatorischer Anforderungen. Der Geltungsbereich muss mindestens jährlich überprüft und an organisatorische Veränderungen angepasst werden.",
      descriptionEn: "We must clearly define the scope of security monitoring. All business-critical systems, networks, applications, and data processing activities must be included in monitoring. Objectives encompass detection of security incidents, identification of anomalies, support of forensic analyses, and compliance with regulatory requirements. The scope must be reviewed at least annually and adapted to organisational changes.",
      reason: "Ohne klare Definition des Überwachungsumfangs entstehen blinde Flecken, die Angreifer ausnutzen können. NIS2 fordert explizit eine umfassende Sicherheitsüberwachung.",
      reasonEn: "Without clear definition of monitoring scope, blind spots arise that attackers can exploit. NIS2 explicitly requires comprehensive security monitoring.",
      whenRequired: "Immer erforderlich als Grundlage für alle weiteren Überwachungsmaßnahmen.",
      whenRequiredEn: "Always required as the foundation for all further monitoring measures.",
      sources: ["ISO 27001:2022 A.8.15-A.8.16", "NIS2 Art.21(2)(b)", "BSI IT-Grundschutz OPS.1.1.5", "NIST CSF 2.0 DE.CM"] },

    { id: "p26-c01", title: "Kontinuierliche Überwachung kritischer Systeme", titleEn: "Continuous Monitoring of Critical Systems",
      description: "Alle als kritisch eingestuften Systeme und Infrastrukturkomponenten müssen einer kontinuierlichen Echtzeit-Überwachung (24/7) unterzogen werden. Dies umfasst Server, Datenbanken, Netzwerkkomponenten, Sicherheitsinfrastruktur (Firewalls, IDS/IPS) und cloud-basierte Dienste. Die Überwachung muss sowohl Verfügbarkeit als auch Sicherheitsmetriken erfassen. Ausfälle der Überwachung selbst müssen automatisch erkannt und eskaliert werden.",
      descriptionEn: "All systems and infrastructure components classified as critical must undergo continuous real-time monitoring (24/7). This includes servers, databases, network components, security infrastructure (firewalls, IDS/IPS), and cloud-based services. Monitoring must capture both availability and security metrics. Failures of the monitoring system itself must be automatically detected and escalated.",
      reason: "Kritische Systeme sind bevorzugte Angriffsziele. Nur eine lückenlose Echtzeitüberwachung ermöglicht die frühzeitige Erkennung von Kompromittierungen und minimiert die Auswirkung von Vorfällen.",
      reasonEn: "Critical systems are preferred attack targets. Only continuous real-time monitoring enables early detection of compromises and minimises the impact of incidents.",
      whenRequired: "Erforderlich für alle Organisationen, die kritische IT-Systeme betreiben.",
      whenRequiredEn: "Required for all organisations operating critical IT systems.",
      sources: ["ISO 27001:2022 A.8.16", "NIS2 Art.21(2)(b)", "BSI IT-Grundschutz OPS.1.1.5", "NIST CSF 2.0 DE.CM-01"] },

    { id: "p26-c02", title: "Netzwerkverkehrsüberwachung und Anomalieerkennung", titleEn: "Network Traffic Monitoring & Anomaly Detection",
      description: "Wir müssen den Netzwerkverkehr an allen kritischen Netzwerkübergängen und innerhalb sensibler Netzwerksegmente überwachen. Hierzu gehören Analyse des Datenverkehrsvolumens, Protokollanalyse, Deep Packet Inspection (DPI) bei Bedarf und die Erkennung ungewöhnlicher Kommunikationsmuster. Baseline-Profile für normales Verkehrsverhalten müssen erstellt und kontinuierlich aktualisiert werden. Abweichungen müssen automatisch Alarme auslösen.",
      descriptionEn: "We must monitor network traffic at all critical network boundaries and within sensitive network segments. This includes analysis of traffic volume, protocol analysis, Deep Packet Inspection (DPI) when needed, and detection of unusual communication patterns. Baseline profiles for normal traffic behaviour must be created and continuously updated. Deviations must automatically trigger alerts.",
      reason: "Netzwerkanomalien sind häufig erste Indikatoren für laufende Angriffe wie Lateral Movement, Datenexfiltration oder Command-and-Control-Kommunikation. Ohne Netzwerküberwachung bleiben diese unentdeckt.",
      reasonEn: "Network anomalies are frequently the first indicators of ongoing attacks such as lateral movement, data exfiltration, or command-and-control communication. Without network monitoring, these remain undetected.",
      whenRequired: "Erforderlich für alle Organisationen mit verteilten Netzwerken oder Internetzugang.",
      whenRequiredEn: "Required for all organisations with distributed networks or internet access.",
      sources: ["ISO 27001:2022 A.8.16", "NIS2 Art.21(2)(b)", "BSI IT-Grundschutz NET.1.2", "NIST CSF 2.0 DE.CM-01"] },

    { id: "p26-c03", title: "Benutzeraktivitätsüberwachung", titleEn: "User Activity Monitoring",
      description: "Wir müssen Benutzeraktivitäten überwachen, insbesondere bei privilegierten Konten, administrativem Zugriff und Zugriffen auf sensible Daten. Die Überwachung umfasst Anmeldemuster, Zugriffshäufigkeit, ungewöhnliche Arbeitszeiten, geografische Anomalien und Massenaktionen auf Daten. Dabei müssen Datenschutzanforderungen (DSGVO, Betriebsvereinbarungen) strikt eingehalten werden. Eine Mitarbeiterinformation über Art und Umfang der Überwachung ist verpflichtend.",
      descriptionEn: "We must monitor user activities, particularly for privileged accounts, administrative access, and access to sensitive data. Monitoring includes login patterns, access frequency, unusual working hours, geographic anomalies, and bulk data actions. Privacy requirements (GDPR, works agreements) must be strictly observed. Employee notification about the type and scope of monitoring is mandatory.",
      reason: "Kompromittierte Benutzerkonten und Insider-Bedrohungen gehören zu den häufigsten Ursachen von Sicherheitsvorfällen. Nur durch Aktivitätsüberwachung können diese rechtzeitig erkannt werden.",
      reasonEn: "Compromised user accounts and insider threats are among the most common causes of security incidents. Only through activity monitoring can these be detected in time.",
      whenRequired: "Erforderlich insbesondere für Organisationen mit privilegierten Zugängen und sensiblen Daten.",
      whenRequiredEn: "Required especially for organisations with privileged access and sensitive data.",
      sources: ["ISO 27001:2022 A.8.15", "DSGVO Art.6, Art.13", "BSI IT-Grundschutz OPS.1.1.5", "NIST CSF 2.0 DE.CM-03"] },

    { id: "p26-c04", title: "Alarmmanagement und Priorisierung", titleEn: "Alert Management & Prioritisation",
      description: "Wir müssen ein strukturiertes Alarmmanagement implementieren. Alarme müssen nach Schweregrad (kritisch, hoch, mittel, niedrig) kategorisiert und mit definierten Reaktionszeiten versehen werden. Kritische Alarme erfordern sofortige Reaktion (innerhalb von 15 Minuten), hohe Alarme innerhalb von 1 Stunde. Falsch-Positiv-Raten müssen systematisch erfasst und Alarmregeln kontinuierlich optimiert werden, um Alert Fatigue zu vermeiden.",
      descriptionEn: "We must implement structured alert management. Alerts must be categorised by severity (critical, high, medium, low) with defined response times. Critical alerts require immediate response (within 15 minutes), high alerts within 1 hour. False positive rates must be systematically captured and alert rules continuously optimised to avoid alert fatigue.",
      reason: "Ohne priorisiertes Alarmmanagement werden kritische Sicherheitsereignisse in einer Flut von Meldungen übersehen (Alert Fatigue). Strukturierte Priorisierung stellt sicher, dass die wichtigsten Vorfälle zuerst behandelt werden.",
      reasonEn: "Without prioritised alert management, critical security events are overlooked in a flood of notifications (alert fatigue). Structured prioritisation ensures the most important incidents are handled first.",
      whenRequired: "Erforderlich sobald Überwachungssysteme Alarme generieren.",
      whenRequiredEn: "Required as soon as monitoring systems generate alerts.",
      sources: ["ISO 27001:2022 A.8.16", "BSI IT-Grundschutz DER.1", "NIST CSF 2.0 DE.AE-02"] },

    { id: "p26-c05", title: "Integritätsüberwachung (File Integrity Monitoring)", titleEn: "File Integrity Monitoring (FIM)",
      description: "Kritische System- und Konfigurationsdateien müssen durch File-Integrity-Monitoring-Lösungen überwacht werden. Dies umfasst Betriebssystemdateien, Anwendungskonfigurationen, Sicherheitsrichtlinien-Dateien und Boot-Sektoren. Änderungen an überwachten Dateien müssen in Echtzeit erkannt und mit genehmigten Change-Tickets abgeglichen werden. Nicht autorisierte Änderungen müssen sofort als Sicherheitsereignis eskaliert werden.",
      descriptionEn: "Critical system and configuration files must be monitored through file integrity monitoring solutions. This includes operating system files, application configurations, security policy files, and boot sectors. Changes to monitored files must be detected in real-time and reconciled with approved change tickets. Unauthorised changes must be immediately escalated as security events.",
      reason: "Dateimanipulation ist ein Schlüsselindikator für Kompromittierungen, einschließlich Rootkits, Backdoors und Ransomware. FIM erkennt solche Änderungen bevor weiterer Schaden entsteht.",
      reasonEn: "File manipulation is a key indicator of compromise, including rootkits, backdoors, and ransomware. FIM detects such changes before further damage occurs.",
      whenRequired: "Erforderlich für Server, kritische Anwendungen und Sicherheitsinfrastruktur.",
      whenRequiredEn: "Required for servers, critical applications, and security infrastructure.",
      sources: ["ISO 27001:2022 A.8.16", "BSI IT-Grundschutz SYS.1.1", "NIST CSF 2.0 DE.CM-01", "PCI DSS 4.0 Req.11.5"] },

    { id: "p26-c06", title: "Verfügbarkeits- und Performance-Monitoring", titleEn: "Availability & Performance Monitoring",
      description: "Wir müssen die Verfügbarkeit und Leistung aller kritischen Dienste kontinuierlich überwachen. Metriken wie Antwortzeiten, CPU-/Speicherauslastung, Festplattenkapazität und Netzwerkbandbreite müssen erfasst und gegen definierte Schwellenwerte geprüft werden. Kapazitätsengpässe müssen frühzeitig erkannt werden, bevor sie zu Ausfällen führen. Dashboards für den Überblick über den Gesamtstatus müssen verfügbar sein.",
      descriptionEn: "We must continuously monitor the availability and performance of all critical services. Metrics such as response times, CPU/memory utilisation, disk capacity, and network bandwidth must be captured and checked against defined thresholds. Capacity bottlenecks must be detected early before they lead to outages. Dashboards providing an overview of the overall status must be available.",
      reason: "Leistungseinbrüche und Kapazitätsengpässe können Vorboten von DDoS-Angriffen, Kryptomining-Malware oder System-Kompromittierungen sein. Proaktive Überwachung ermöglicht präventive Maßnahmen.",
      reasonEn: "Performance degradation and capacity bottlenecks can be precursors to DDoS attacks, cryptomining malware, or system compromises. Proactive monitoring enables preventive measures.",
      whenRequired: "Erforderlich für alle kritischen Systeme und Dienste.",
      whenRequiredEn: "Required for all critical systems and services.",
      sources: ["ISO 27001:2022 A.8.6", "BSI IT-Grundschutz OPS.1.1.5", "NIST CSF 2.0 DE.CM-01"] },

    { id: "p26-c07", title: "Cloud-Umgebungsüberwachung", titleEn: "Cloud Environment Monitoring",
      description: "Cloud-basierte Infrastruktur, Plattformen und Anwendungen müssen in die Sicherheitsüberwachung integriert werden. Dies umfasst die Überwachung von Cloud-Konfigurationsänderungen, IAM-Aktivitäten, API-Aufrufen, Datenexfiltrations-Indikatoren und der Einhaltung von Cloud-Sicherheitsrichtlinien. Cloud Security Posture Management (CSPM)-Tools sollten eingesetzt werden, um Fehlkonfigurationen automatisch zu erkennen.",
      descriptionEn: "Cloud-based infrastructure, platforms, and applications must be integrated into security monitoring. This includes monitoring of cloud configuration changes, IAM activities, API calls, data exfiltration indicators, and compliance with cloud security policies. Cloud Security Posture Management (CSPM) tools should be deployed to automatically detect misconfigurations.",
      reason: "Cloud-Umgebungen haben spezifische Risiken wie Fehlkonfigurationen, über-privilegierte Konten und Shadow-IT. Ohne spezifische Cloud-Überwachung bleiben diese Risiken unsichtbar.",
      reasonEn: "Cloud environments have specific risks such as misconfigurations, over-privileged accounts, and shadow IT. Without specific cloud monitoring, these risks remain invisible.",
      whenRequired: "Erforderlich für alle Organisationen, die Cloud-Dienste nutzen.",
      whenRequiredEn: "Required for all organisations using cloud services.",
      sources: ["ISO 27001:2022 A.8.16", "BSI C5:2020", "NIST CSF 2.0 DE.CM-01", "CSA CCM 4.0"] },

    { id: "p26-c08", title: "Bedrohungsintelligenz-Integration", titleEn: "Threat Intelligence Integration",
      description: "Wir müssen Bedrohungsintelligenz (Threat Intelligence) in unsere Überwachungssysteme integrieren. Dies umfasst die Nutzung von Indicators of Compromise (IoC), Indicators of Attack (IoA), Bedrohungs-Feeds von CERTs, ISAC/ISAO und kommerziellen Anbietern. IoC-Feeds müssen automatisch in SIEM-Systeme und Firewalls eingespeist werden. Bedrohungsinformationen müssen kontextualisiert und auf die spezifische Branche und das Risikoprofil der Organisation bezogen werden.",
      descriptionEn: "We must integrate threat intelligence into our monitoring systems. This includes the use of Indicators of Compromise (IoC), Indicators of Attack (IoA), threat feeds from CERTs, ISAC/ISAO, and commercial providers. IoC feeds must be automatically ingested into SIEM systems and firewalls. Threat information must be contextualised and related to the specific industry and risk profile of the organisation.",
      reason: "Ohne aktuelle Bedrohungsintelligenz kann die Organisation neue Angriffsmuster und Bedrohungen nicht rechtzeitig erkennen. Die Integration in die Überwachung ermöglicht proaktive Verteidigung.",
      reasonEn: "Without current threat intelligence, we cannot detect new attack patterns and threats in time. Integration into monitoring enables proactive defence.",
      whenRequired: "Dringend empfohlen für alle Organisationen, insbesondere im Bereich kritischer Infrastruktur.",
      whenRequiredEn: "Strongly recommended for all organisations, especially in critical infrastructure sectors.",
      sources: ["ISO 27001:2022 A.5.7", "NIS2 Art.21(2)(b)", "BSI IT-Grundschutz DER.1", "NIST CSF 2.0 DE.AE-02"] },

    { id: "p26-c09", title: "Endpunkt-Erkennung und -Reaktion (EDR) — Überwachungsintegration", titleEn: "Endpoint Detection & Response (EDR) — Monitoring Integration",
      description: "Wir müssen auf allen Endpunkten (Workstations, Laptops, Server) Endpoint Detection & Response (EDR)-Lösungen in die zentrale Sicherheitsüberwachung integrieren. Diese Klausel regelt die operative Einbindung von EDR-Telemetrie in das Überwachungs- und Alarmmanagement: verhaltensbasierte Erkennungsergebnisse müssen automatisch an das zentrale SIEM/SOC gemeldet, korreliert und priorisiert werden. Die strategische EDR-Architektur, Rollout-Strategie und Compliance-Anforderungen an Endpunkte werden in p17 (Endpoint Security) geregelt.",
      descriptionEn: "We must integrate Endpoint Detection & Response (EDR) solutions on all endpoints (workstations, laptops, servers) into central security monitoring. This clause governs the operational integration of EDR telemetry into monitoring and alert management: behaviour-based detection results must be automatically reported to the central SIEM/SOC, correlated, and prioritised. Strategic EDR architecture, rollout strategy, and endpoint compliance requirements are governed by p17 (Endpoint Security).",
      reason: "Herkömmliche Antivirus-Lösungen erkennen fortgeschrittene Bedrohungen wie fileless malware, Living-off-the-Land-Angriffe und Zero-Day-Exploits nicht. Die operative Integration von EDR-Telemetrie in die zentrale Überwachung stellt sicher, dass Endpunkt-Bedrohungen im Gesamtkontext erkannt werden.",
      reasonEn: "Traditional antivirus solutions do not detect advanced threats such as fileless malware, living-off-the-land attacks, and zero-day exploits. Operational integration of EDR telemetry into central monitoring ensures endpoint threats are detected in the overall context.",
      whenRequired: "Erforderlich für alle verwalteten Endpunkte. Siehe p17 für strategische EDR-Architektur.",
      whenRequiredEn: "Required for all managed endpoints. See p17 for strategic EDR architecture.",
      sources: ["ISO 27001:2022 A.8.7", "BSI IT-Grundschutz SYS.2.1", "NIST CSF 2.0 DE.CM-01"] },

    { id: "p26-c10", title: "Überwachung der physischen Sicherheit", titleEn: "Physical Security Monitoring",
      description: "Zutrittskontrollen, Videoüberwachung und Umgebungssensoren (Temperatur, Feuchtigkeit, Wassereinbruch, Rauch) müssen in die zentrale Überwachung integriert werden. Unberechtigte Zutrittsversuche und Umgebungsanomalien müssen automatisch Alarme auslösen. Videoüberwachungsdaten müssen für definierte Zeiträume aufbewahrt werden und für forensische Zwecke abrufbar sein.",
      descriptionEn: "Access controls, video surveillance, and environmental sensors (temperature, humidity, water ingress, smoke) must be integrated into central monitoring. Unauthorised access attempts and environmental anomalies must automatically trigger alerts. Video surveillance data must be retained for defined periods and be retrievable for forensic purposes.",
      reason: "Physische Sicherheitsverletzungen können zu Datendiebstahl, Sabotage oder Manipulation kritischer Systeme führen. Die Integration in die IT-Überwachung ermöglicht korrelierte Analysen.",
      reasonEn: "Physical security breaches can lead to data theft, sabotage, or manipulation of critical systems. Integration into IT monitoring enables correlated analyses.",
      whenRequired: "Erforderlich für Rechenzentren, Serverräume und kritische Infrastrukturstandorte.",
      whenRequiredEn: "Required for data centres, server rooms, and critical infrastructure locations.",
      sources: ["ISO 27001:2022 A.7.1-A.7.4", "BSI IT-Grundschutz INF.2", "NIST CSF 2.0 DE.CM-02"] },

    { id: "p26-c11", title: "Datenexfiltrations-Erkennung (DLP-Monitoring) — Überwachungsebene", titleEn: "Data Exfiltration Detection (DLP Monitoring) — Monitoring Layer",
      description: "Wir müssen Maßnahmen zur Erkennung von Datenexfiltration in die operative Sicherheitsüberwachung integrieren. Dies umfasst die Echtzeitüberwachung von E-Mail-Anhängen, Cloud-Uploads, USB-Transfers, ungewöhnlichen Datenbankabfragen und verschlüsselten Kanälen. DLP-Alarme müssen in das zentrale Alarmmanagement (p26-c04) einfließen und priorisiert werden. Die technischen DLP-Regeln auf Datenträgerebene und die Datenklassifizierungspolitik werden in p24-c14 (Medienbasierte DLP-Kontrollen) geregelt.",
      descriptionEn: "We must integrate data exfiltration detection measures into operational security monitoring. This includes real-time monitoring of email attachments, cloud uploads, USB transfers, unusual database queries, and encrypted channels. DLP alerts must flow into central alert management (p26-c04) and be prioritised. Technical DLP rules at media level and data classification policy are governed by p24-c14 (Media-Based DLP Controls).",
      reason: "Datenexfiltration ist häufig das Hauptziel von Cyberangriffen. Die operative Integration von DLP-Alarmen in die zentrale Überwachung stellt sicher, dass verdächtige Datenbewegungen im Gesamtkontext bewertet werden.",
      reasonEn: "Data exfiltration is frequently the primary goal of cyber attacks. Operational integration of DLP alerts into central monitoring ensures suspicious data movements are assessed in the overall context.",
      whenRequired: "Erforderlich für Organisationen, die vertrauliche, personenbezogene oder regulierte Daten verarbeiten. Siehe p24-c14 für medienbasierte DLP-Kontrollen.",
      whenRequiredEn: "Required for organisations processing confidential, personal, or regulated data. See p24-c14 for media-based DLP controls.",
      sources: ["ISO 27001:2022 A.8.12", "DSGVO Art.32", "BSI IT-Grundschutz OPS.1.1.5", "NIST CSF 2.0 DE.CM-01"] },

    { id: "p26-c12", title: "Privileged Access Monitoring — Überwachungsebene", titleEn: "Privileged Access Monitoring — Monitoring Layer",
      description: "Alle Aktivitäten privilegierter Konten (Administratoren, Root, Service-Accounts) müssen in Echtzeit in das zentrale Überwachungssystem integriert werden. PAM-Telemetrie (Session-Recording-Alarme, Anomalien, ungenehmigte Eskalationen) muss automatisch an das SOC/SIEM gemeldet werden. Ungewöhnliche Aktionen wie Massenänderungen, Richtlinien-Deaktivierung oder unplanmäßiger Zugriff müssen sofort Alarme auslösen. Die technische PAM-Architektur (JIT-Zugang, Credential Vaulting, Session-Recording-Infrastruktur) wird in p12 (Privileged Access Management) geregelt.",
      descriptionEn: "All activities of privileged accounts (administrators, root, service accounts) must be integrated into the central monitoring system in real-time. PAM telemetry (session recording alerts, anomalies, unauthorised escalations) must be automatically reported to the SOC/SIEM. Unusual actions such as bulk changes, policy deactivation, or unscheduled access must immediately trigger alerts. Technical PAM architecture (JIT access, credential vaulting, session recording infrastructure) is governed by p12 (Privileged Access Management).",
      reason: "Privilegierte Konten bieten Angreifern die größtmögliche Kontrolle über Systeme. Die operative Integration der PAM-Überwachung in das zentrale Monitoring stellt sicher, dass privilegierte Anomalien im Gesamtkontext bewertet werden.",
      reasonEn: "Privileged accounts provide attackers with maximum control over systems. Operational integration of PAM monitoring into central monitoring ensures privileged anomalies are assessed in the overall context.",
      whenRequired: "Erforderlich für alle Organisationen mit administrativem Zugang. Siehe p12 für technische PAM-Architektur.",
      whenRequiredEn: "Required for all organisations with administrative access. See p12 for technical PAM architecture.",
      sources: ["ISO 27001:2022 A.8.2, A.8.15", "BSI IT-Grundschutz OPS.1.1.2", "NIST CSF 2.0 DE.CM-03"] },

    { id: "p26-c13", title: "Security Operations Centre (SOC) Organisation", titleEn: "Security Operations Centre (SOC) Organisation",
      description: "Wir müssen definieren, ob ein internes SOC, ein externes SOC (MSSP/MDR) oder eine hybride Lösung die Sicherheitsüberwachung durchführt. Rollen, Verantwortlichkeiten und Eskalationswege müssen klar definiert sein. SLA-Anforderungen für Erkennungs- und Reaktionszeiten müssen vertraglich oder intern festgelegt werden. Bei Nutzung externer SOC-Dienste muss die Kontrolle über kritische Entscheidungen bei der Organisation verbleiben.",
      descriptionEn: "We must define whether an internal SOC, external SOC (MSSP/MDR), or hybrid solution performs security monitoring. Roles, responsibilities, and escalation paths must be clearly defined. SLA requirements for detection and response times must be contractually or internally established. When using external SOC services, control over critical decisions must remain with the organisation.",
      reason: "Effektive Sicherheitsüberwachung erfordert dedizierte Ressourcen und Expertise. Die organisatorische Verankerung stellt sicher, dass Überwachung nicht nur technisch, sondern auch prozessual funktioniert.",
      reasonEn: "Effective security monitoring requires dedicated resources and expertise. The organisational anchoring ensures that monitoring works not only technically but also procedurally.",
      whenRequired: "Erforderlich für Organisationen mit komplexen IT-Umgebungen oder regulatorischen Anforderungen an kontinuierliche Überwachung.",
      whenRequiredEn: "Required for organisations with complex IT environments or regulatory requirements for continuous monitoring.",
      sources: ["ISO 27001:2022 A.5.24", "NIS2 Art.21(2)(b)", "BSI IT-Grundschutz DER.1", "NIST CSF 2.0 DE"] },

    { id: "p26-c14", title: "Erkennungsmetriken und Wirksamkeitsmessung", titleEn: "Detection Metrics & Effectiveness Measurement",
      description: "Wir müssen KPIs und Metriken für die Überwachungseffektivität definieren und regelmäßig messen. Wesentliche Metriken umfassen: Mean Time to Detect (MTTD), Mean Time to Respond (MTTR), Falsch-Positiv-Rate, Abdeckungsgrad der Überwachung, Anzahl unbehandelter Alarme und Erfolgsrate bei Erkennungstests. Metriken müssen monatlich berichtet und zur kontinuierlichen Verbesserung genutzt werden.",
      descriptionEn: "We must define and regularly measure KPIs and metrics for monitoring effectiveness. Key metrics include: Mean Time to Detect (MTTD), Mean Time to Respond (MTTR), false positive rate, monitoring coverage ratio, number of unhandled alerts, and success rate in detection tests. Metrics must be reported monthly and used for continuous improvement.",
      reason: "Ohne Wirksamkeitsmessung kann die Organisation nicht beurteilen, ob ihre Überwachung tatsächlich funktioniert. Metriken ermöglichen datengetriebene Verbesserungen und nachweisbare Compliance.",
      reasonEn: "Without effectiveness measurement, we cannot assess whether our monitoring actually works. Metrics enable data-driven improvements and demonstrable compliance.",
      whenRequired: "Erforderlich für jede Organisation, die Sicherheitsüberwachung betreibt.",
      whenRequiredEn: "Required for every organisation performing security monitoring.",
      sources: ["ISO 27001:2022 §9.1", "BSI IT-Grundschutz DER.1", "NIST CSF 2.0 DE.AE"] },

    { id: "p26-c15", title: "Automatisierte Reaktion und Orchestrierung (SOAR)", titleEn: "Automated Response & Orchestration (SOAR)",
      description: "Wir sollen Security Orchestration, Automation and Response (SOAR)-Fähigkeiten implementieren, um wiederkehrende Erkennungs- und Reaktionsaufgaben zu automatisieren. Automatisierte Playbooks müssen für häufige Bedrohungsszenarien (Phishing, Malware, Brute-Force-Angriffe) erstellt werden. Vollautomatische Aktionen (z.B. Kontosperrung, IP-Blockierung) dürfen nur nach sorgfältiger Risikoabwägung und mit definierten Rücknahme-Prozeduren aktiviert werden.",
      descriptionEn: "We should implement Security Orchestration, Automation and Response (SOAR) capabilities to automate recurring detection and response tasks. Automated playbooks must be created for common threat scenarios (phishing, malware, brute-force attacks). Fully automated actions (e.g., account lockout, IP blocking) may only be enabled after careful risk assessment and with defined rollback procedures.",
      reason: "Manuelle Bearbeitung aller Sicherheitsereignisse ist bei wachsendem Volumen nicht skalierbar. Automatisierung reduziert Reaktionszeiten und entlastet Sicherheitsteams für komplexe Analysen.",
      reasonEn: "Manual handling of all security events is not scalable with growing volume. Automation reduces response times and frees security teams for complex analyses.",
      whenRequired: "Empfohlen für Organisationen mit hohem Alarmvolumen oder begrenzten SOC-Ressourcen.",
      whenRequiredEn: "Recommended for organisations with high alert volume or limited SOC resources.",
      sources: ["ISO 27001:2022 A.8.16", "BSI IT-Grundschutz DER.1", "NIST CSF 2.0 RS.RP"] },

    { id: "p26-c16", title: "Erkennung lateraler Bewegungen (Lateral Movement Detection)", titleEn: "Lateral Movement Detection",
      description: "Wir müssen spezifische Erkennungsmechanismen für laterale Bewegungen innerhalb des Netzwerks implementieren. Dies umfasst die Überwachung ungewöhnlicher Authentifizierungen zwischen Systemen, die Nutzung von Remote-Verwaltungstools (PsExec, WMI, PowerShell Remoting), Pass-the-Hash/Ticket-Angriffe und die Eskalation von Privilegien. Honeypots und Deception-Technologien können ergänzend eingesetzt werden.",
      descriptionEn: "We must implement specific detection mechanisms for lateral movement within the network. This includes monitoring unusual authentications between systems, use of remote administration tools (PsExec, WMI, PowerShell Remoting), pass-the-hash/ticket attacks, and privilege escalation. Honeypots and deception technologies may be used supplementarily.",
      reason: "Laterale Bewegung ist eine zentrale Phase fortgeschrittener Angriffe (APTs). Die Erkennung in dieser Phase verhindert die vollständige Kompromittierung des Netzwerks.",
      reasonEn: "Lateral movement is a central phase of advanced attacks (APTs). Detection in this phase prevents complete compromise of the network.",
      whenRequired: "Erforderlich für Organisationen mit segmentierten Netzwerken und hohem Schutzbedarf.",
      whenRequiredEn: "Required for organisations with segmented networks and high protection needs.",
      sources: ["ISO 27001:2022 A.8.16", "BSI IT-Grundschutz DER.1", "NIST CSF 2.0 DE.CM-01", "MITRE ATT&CK TA0008"] },

    { id: "p26-c17", title: "DNS- und E-Mail-Überwachung", titleEn: "DNS & Email Monitoring",
      description: "DNS-Anfragen und E-Mail-Verkehr müssen überwacht werden, um Bedrohungen wie DNS-Tunneling, Domain Generation Algorithms (DGA), Phishing, Business Email Compromise (BEC) und Malware-Verteilung zu erkennen. DNS-Logs müssen zentral gesammelt und analysiert werden. E-Mail-Gateways müssen verdächtige Anhänge und Links erkennen und blockieren. Ungewöhnliche DNS-Muster müssen automatisch Alarme auslösen.",
      descriptionEn: "DNS queries and email traffic must be monitored to detect threats such as DNS tunnelling, Domain Generation Algorithms (DGA), phishing, Business Email Compromise (BEC), and malware distribution. DNS logs must be centrally collected and analysed. Email gateways must detect and block suspicious attachments and links. Unusual DNS patterns must automatically trigger alerts.",
      reason: "DNS und E-Mail sind die häufigsten Angriffsvektoren. DNS wird von nahezu jeder Malware für C2-Kommunikation genutzt, E-Mail ist der Hauptvektor für Phishing und Malware-Verteilung.",
      reasonEn: "DNS and email are the most common attack vectors. DNS is used by nearly every malware for C2 communication, email is the primary vector for phishing and malware distribution.",
      whenRequired: "Erforderlich für alle Organisationen mit Internetzugang und E-Mail-Systemen.",
      whenRequiredEn: "Required for all organisations with internet access and email systems.",
      sources: ["ISO 27001:2022 A.8.16", "BSI IT-Grundschutz APP.5.3", "NIST CSF 2.0 DE.CM-01"] },

    { id: "p26-c18", title: "Überwachung von Drittanbieter- und Supply-Chain-Zugängen — Monitoring-Ebene", titleEn: "Third-Party & Supply Chain Access Monitoring — Monitoring Layer",
      description: "Alle Zugänge und Aktivitäten von Drittanbietern, Dienstleistern und Lieferanten innerhalb der IT-Umgebung der Organisation müssen in die operative Sicherheitsüberwachung integriert werden. VPN-Zugriffe, Remote-Desktop-Sitzungen und API-Verbindungen von externen Parteien müssen in Echtzeit überwacht und auf Anomalien geprüft werden. Drittanbieter-Zugriffe müssen zeitlich begrenzt und nach Abschluss der Arbeiten deaktiviert werden. Die vertraglichen, organisatorischen und strategischen Anforderungen an Lieferantensicherheit (Bewertung, Vertragsklauseln, Audit-Rechte) werden in p42/p43 (Supplier Security) geregelt.",
      descriptionEn: "All access and activities of third parties, service providers, and suppliers within the organisation's IT environment must be integrated into operational security monitoring. VPN access, remote desktop sessions, and API connections from external parties must be monitored in real-time and checked for anomalies. Third-party access must be time-limited and deactivated upon completion of work. Contractual, organisational, and strategic supplier security requirements (assessments, contract clauses, audit rights) are governed by p42/p43 (Supplier Security).",
      reason: "Supply-Chain-Angriffe nehmen stark zu. Drittanbieter mit Zugang zu internen Systemen stellen ein erhebliches Risiko dar, das durch konsequente operative Überwachung kontrolliert werden muss.",
      reasonEn: "Supply chain attacks are increasing significantly. Third parties with access to internal systems pose a significant risk that must be controlled through consistent operational monitoring.",
      whenRequired: "Erforderlich für alle Organisationen, die externen Parteien Zugang gewähren. Siehe p42/p43 für strategische Lieferantensicherheit.",
      whenRequiredEn: "Required for all organisations granting external parties access. See p42/p43 for strategic supplier security.",
      sources: ["ISO 27001:2022 A.5.19-A.5.22", "NIS2 Art.21(2)(d)", "BSI IT-Grundschutz OPS.2.1", "NIST CSF 2.0 DE.CM-06"] },

    { id: "p26-c19", title: "Erkennungstests und Red-Team-Übungen", titleEn: "Detection Testing & Red Team Exercises",
      description: "Die Wirksamkeit der Überwachungssysteme muss regelmäßig durch simulierte Angriffe (Purple Teaming, Red Team Exercises) getestet werden. Tests müssen reale Angriffsszenarien abbilden und prüfen, ob die Erkennung, Alarmierung und Eskalation funktionieren. Defizite müssen dokumentiert und durch Verbesserungsmaßnahmen adressiert werden. Erkennungstests müssen mindestens halbjährlich durchgeführt werden.",
      descriptionEn: "The effectiveness of monitoring systems must be regularly tested through simulated attacks (purple teaming, red team exercises). Tests must simulate real attack scenarios and verify whether detection, alerting, and escalation work. Deficits must be documented and addressed through improvement measures. Detection tests must be conducted at least semi-annually.",
      reason: "Überwachungssysteme können nur dann als wirksam gelten, wenn sie regelmäßig unter realistischen Bedingungen getestet werden. Ohne Tests bleiben Lücken in der Erkennung unentdeckt.",
      reasonEn: "Monitoring systems can only be considered effective when they are regularly tested under realistic conditions. Without tests, gaps in detection remain undiscovered.",
      whenRequired: "Erforderlich für Organisationen mit hohem Schutzbedarf oder regulatorischen Anforderungen.",
      whenRequiredEn: "Required for organisations with high protection needs or regulatory requirements.",
      sources: ["ISO 27001:2022 A.8.16", "NIS2 Art.21(2)(e)", "BSI IT-Grundschutz DER.3.1", "NIST CSF 2.0 DE.AE"] },

    { id: "p26-c20", title: "Überprüfung und Aktualisierung der Überwachungsrichtlinie", titleEn: "Review & Update of Monitoring Policy",
      description: "Diese Richtlinie muss mindestens jährlich oder anlassbezogen (nach Vorfällen, organisatorischen Änderungen, neuen Bedrohungen) überprüft und aktualisiert werden. Die Überprüfung muss die Angemessenheit der Überwachungsmaßnahmen, die Aktualität der Erkennungsregeln und die Ressourcenausstattung bewerten. Änderungen müssen genehmigt, kommuniziert und dokumentiert werden.",
      descriptionEn: "This policy must be reviewed and updated at least annually or event-driven (after incidents, organisational changes, new threats). The review must assess the adequacy of monitoring measures, the currency of detection rules, and resource allocation. Changes must be approved, communicated, and documented.",
      reason: "Die Bedrohungslandschaft ändert sich kontinuierlich. Ohne regelmäßige Aktualisierung veralten Überwachungsregeln und die Erkennungsfähigkeit nimmt ab.",
      reasonEn: "The threat landscape changes continuously. Without regular updates, monitoring rules become outdated and detection capability declines.",
      whenRequired: "Immer erforderlich als Teil des kontinuierlichen Verbesserungsprozesses.",
      whenRequiredEn: "Always required as part of the continuous improvement process.",
      sources: ["ISO 27001:2022 §10.1-10.2", "BSI IT-Grundschutz ISMS.1", "NIST CSF 2.0 GV.OC"] },

    { id: "p26-c21", title: "Darknet- und Credential-Leak-Überwachung", titleEn: "Darknet & Credential Leak Monitoring",
      description: "Wir müssen externe Quellen, einschließlich Darknet-Foren, Paste-Sites und Credential-Leak-Datenbanken, auf Hinweise auf kompromittierte Zugangsdaten, gestohlene Daten oder geplante Angriffe auf die Organisation überwachen. Identifizierte kompromittierte Konten müssen sofort gesperrt und Passwörter zurückgesetzt werden. Die Überwachung kann intern oder durch spezialisierte Dienstleister erfolgen.",
      descriptionEn: "We must monitor external sources, including darknet forums, paste sites, and credential leak databases, for indications of compromised credentials, stolen data, or planned attacks against the organisation. Identified compromised accounts must be immediately locked and passwords reset. Monitoring can be performed internally or through specialised service providers.",
      reason: "Kompromittierte Zugangsdaten werden häufig im Darknet gehandelt, bevor sie für Angriffe verwendet werden. Frühzeitige Erkennung ermöglicht präventive Maßnahmen vor einem tatsächlichen Einbruch.",
      reasonEn: "Compromised credentials are frequently traded on the darknet before being used for attacks. Early detection enables preventive measures before an actual breach.",
      whenRequired: "Empfohlen für alle Organisationen, insbesondere solche mit hoher öffentlicher Sichtbarkeit.",
      whenRequiredEn: "Recommended for all organisations, especially those with high public visibility.",
      sources: ["ISO 27001:2022 A.5.7", "BSI IT-Grundschutz DER.1", "NIST CSF 2.0 DE.CM-01"] },

    { id: "p26-c22", title: "Überwachung von IoT- und OT-Systemen — Monitoring-Integration", titleEn: "IoT & OT System Monitoring — Monitoring Integration",
      description: "Sofern IoT- (Internet of Things) oder OT- (Operational Technology) Systeme vorhanden sind, müssen diese in die zentrale Sicherheitsüberwachung einbezogen werden. Spezifische Protokolle (Modbus, OPC UA, MQTT) müssen analysiert werden können. Die Überwachung muss die Einhaltung der IT/OT-Segmentierung verifizieren und Anomalien in OT-Steuerungsbefehlen erkennen. Die strategische Netzwerksegmentierung zwischen IT- und OT-Zonen sowie die architektonischen Anforderungen an IoT/OT-Netztrennung werden in p16 (Netzwerksicherheit) geregelt.",
      descriptionEn: "Where IoT (Internet of Things) or OT (Operational Technology) systems exist, they must be included in central security monitoring. Specific protocols (Modbus, OPC UA, MQTT) must be analysable. Monitoring must verify compliance with IT/OT segmentation and detect anomalies in OT control commands. Strategic network segmentation between IT and OT zones and architectural requirements for IoT/OT network separation are governed by p16 (Network Security).",
      reason: "IoT/OT-Systeme sind zunehmend Ziel von Cyberangriffen. Die operative Überwachung stellt sicher, dass die in p16 definierte Segmentierung eingehalten wird und protokollspezifische Anomalien erkannt werden.",
      reasonEn: "IoT/OT systems are increasingly targeted by cyber attacks. Operational monitoring ensures that segmentation defined in p16 is maintained and protocol-specific anomalies are detected.",
      whenRequired: "Erforderlich für Organisationen mit IoT-/OT-Systemen. Siehe p16 für strategische Netzwerksegmentierung.",
      whenRequiredEn: "Required for organisations with IoT/OT systems. See p16 for strategic network segmentation.",
      sources: ["ISO 27001:2022 A.8.16", "NIS2 Art.21(2)(b)", "BSI ICS-Security-Kompendium", "NIST CSF 2.0 DE.CM-01"] },
  ],

  // ═══════════════════════════════════════════════════════════════
  // P27 — Logging Policy
  // ═══════════════════════════════════════════════════════════════
  p27: [
    { id: "p27-c00", title: "Geltungsbereich und Ziele der Protokollierung", titleEn: "Scope & Objectives of Logging",
      description: "Wir müssen den Geltungsbereich der Protokollierung festlegen. Alle sicherheitsrelevanten Systeme, Anwendungen, Netzwerkkomponenten und Datenbanken müssen protokolliert werden. Die Ziele der Protokollierung umfassen die Unterstützung der Sicherheitsüberwachung, forensische Analyse, Compliance-Nachweis und Nachvollziehbarkeit administrativer Handlungen. Ausnahmen vom Geltungsbereich müssen schriftlich begründet und genehmigt werden.",
      descriptionEn: "We must define the scope of logging. All security-relevant systems, applications, network components, and databases must be logged. Logging objectives include support for security monitoring, forensic analysis, compliance evidence, and traceability of administrative actions. Exceptions from scope must be justified in writing and approved.",
      reason: "Ohne klare Definition der Protokollierungsanforderungen entstehen Lücken, die forensische Analysen und den Nachweis von Compliance unmöglich machen.",
      reasonEn: "Without clear definition of logging requirements, gaps arise that make forensic analyses and compliance evidence impossible.",
      whenRequired: "Immer erforderlich als Grundlage der Protokollierungsinfrastruktur.",
      whenRequiredEn: "Always required as the foundation of logging infrastructure.",
      sources: ["ISO 27001:2022 A.8.15", "NIS2 Art.21(2)(b)", "BSI IT-Grundschutz OPS.1.1.5", "NIST CSF 2.0 DE.CM"] },

    { id: "p27-c01", title: "Pflichtprotokollereignisse", titleEn: "Mandatory Log Events",
      description: "Folgende Ereignisse müssen mindestens protokolliert werden: erfolgreiche und fehlgeschlagene Authentifizierungen, Änderungen an Benutzerkonten und Berechtigungen, administrative Aktionen, Zugriff auf sensible Daten, Änderungen an Sicherheitskonfigurationen, Systemstart/-stopp, Netzwerkverbindungsversuche, Firewall-Blockierungen, Malware-Erkennungen und alle Änderungen an Audit-Logs selbst. Für jede Ereigniskategorie müssen die zu protokollierenden Felder definiert sein.",
      descriptionEn: "The following events must be logged at minimum: successful and failed authentications, changes to user accounts and permissions, administrative actions, access to sensitive data, changes to security configurations, system start/stop, network connection attempts, firewall blocks, malware detections, and all changes to audit logs themselves. For each event category, the fields to be logged must be defined.",
      reason: "Ohne standardisierte Pflichtprotokollereignisse variiert die Protokollierung zwischen Systemen und kritische Ereignisse werden möglicherweise nicht erfasst.",
      reasonEn: "Without standardised mandatory log events, logging varies between systems and critical events may not be captured.",
      whenRequired: "Immer erforderlich für alle protokollierungspflichtigen Systeme.",
      whenRequiredEn: "Always required for all systems subject to logging requirements.",
      sources: ["ISO 27001:2022 A.8.15", "BSI IT-Grundschutz OPS.1.1.5", "NIST CSF 2.0 DE.CM", "PCI DSS 4.0 Req.10.2"] },

    { id: "p27-c02", title: "Log-Format und Standardisierung", titleEn: "Log Format & Standardisation",
      description: "Alle Protokolle müssen in einem einheitlichen, maschinenlesbaren Format erstellt werden. Empfohlene Formate sind CEF (Common Event Format), JSON oder Syslog (RFC 5424). Jeder Log-Eintrag muss mindestens enthalten: Zeitstempel (UTC), Quell-System, Ereignistyp, Benutzerkennung, Quell-/Ziel-IP, Ergebnis (Erfolg/Fehlschlag) und Schweregrad. Proprietäre Formate müssen in das Standardformat konvertiert werden.",
      descriptionEn: "All logs must be created in a uniform, machine-readable format. Recommended formats are CEF (Common Event Format), JSON, or Syslog (RFC 5424). Each log entry must contain at minimum: timestamp (UTC), source system, event type, user identifier, source/destination IP, result (success/failure), and severity. Proprietary formats must be converted to the standard format.",
      reason: "Heterogene Log-Formate verhindern automatisierte Korrelation und Analyse. Standardisierung ist Voraussetzung für effektives SIEM und forensische Auswertungen.",
      reasonEn: "Heterogeneous log formats prevent automated correlation and analysis. Standardisation is a prerequisite for effective SIEM and forensic evaluations.",
      whenRequired: "Erforderlich für alle Systeme, die in die zentrale Protokollierung eingebunden sind.",
      whenRequiredEn: "Required for all systems integrated into central logging.",
      sources: ["ISO 27001:2022 A.8.15", "BSI IT-Grundschutz OPS.1.1.5", "NIST CSF 2.0 DE.CM"] },

    { id: "p27-c03", title: "Zeitsynchronisation (NTP)", titleEn: "Time Synchronisation (NTP)",
      description: "Alle Systeme, die Protokolle erstellen, müssen zeitlich synchronisiert sein. Die Synchronisation muss über vertrauenswürdige NTP-Server (Network Time Protocol) erfolgen, idealerweise gegen Stratum-1- oder Stratum-2-Zeitquellen. Die maximale Abweichung darf 1 Sekunde nicht überschreiten. Die NTP-Konfiguration muss gegen Manipulation geschützt und regelmäßig überprüft werden.",
      descriptionEn: "All systems generating logs must be time-synchronised. Synchronisation must occur via trusted NTP (Network Time Protocol) servers, ideally against Stratum 1 or Stratum 2 time sources. Maximum deviation must not exceed 1 second. NTP configuration must be protected against tampering and regularly verified.",
      reason: "Ohne Zeitsynchronisation können Protokolleinträge verschiedener Systeme nicht korreliert werden. Dies macht forensische Analysen und die Rekonstruktion von Angriffspfaden unmöglich.",
      reasonEn: "Without time synchronisation, log entries from different systems cannot be correlated. This makes forensic analyses and reconstruction of attack paths impossible.",
      whenRequired: "Immer erforderlich für alle protokollierenden Systeme.",
      whenRequiredEn: "Always required for all logging systems.",
      sources: ["ISO 27001:2022 A.8.17", "BSI IT-Grundschutz OPS.1.1.5", "NIST CSF 2.0 DE.CM", "PCI DSS 4.0 Req.10.6"] },

    { id: "p27-c04", title: "Zentrale Protokollsammlung und -aggregation", titleEn: "Central Log Collection & Aggregation",
      description: "Alle Protokolle müssen zentral gesammelt, aggregiert und gespeichert werden. Die Übertragung von Protokollen an die zentrale Sammelstelle muss verschlüsselt erfolgen (z.B. TLS). Ein Puffer- oder Warteschlangenmechanismus muss sicherstellen, dass keine Protokolle bei temporären Verbindungsausfällen verloren gehen. Die zentrale Protokollinfrastruktur muss hochverfügbar ausgelegt sein.",
      descriptionEn: "All logs must be centrally collected, aggregated, and stored. Transmission of logs to the central collection point must be encrypted (e.g., TLS). A buffering or queuing mechanism must ensure no logs are lost during temporary connection failures. The central logging infrastructure must be designed for high availability.",
      reason: "Dezentrale Protokollspeicherung verhindert übergreifende Korrelation und kann von Angreifern manipuliert werden. Zentrale Sammlung ermöglicht einheitliche Analyse und sichert die Integrität.",
      reasonEn: "Decentralised log storage prevents cross-system correlation and can be manipulated by attackers. Central collection enables unified analysis and ensures integrity.",
      whenRequired: "Erforderlich für alle Organisationen mit mehr als einer Protokollquelle.",
      whenRequiredEn: "Required for all organisations with more than one log source.",
      sources: ["ISO 27001:2022 A.8.15", "BSI IT-Grundschutz OPS.1.1.5", "NIST CSF 2.0 DE.CM"] },

    { id: "p27-c05", title: "Integritätsschutz von Protokolldaten", titleEn: "Log Data Integrity Protection",
      description: "Protokolldaten müssen gegen Manipulation, Löschung und unautorisierten Zugriff geschützt werden. Write-Once-Read-Many (WORM)-Speicher oder kryptographische Hashketten müssen eingesetzt werden, um die Integrität zu gewährleisten. Der Zugriff auf Protokolldaten muss auf autorisiertes Personal beschränkt sein. Änderungen an der Protokollkonfiguration müssen selbst protokolliert werden. Versuche, Protokolle zu löschen oder zu manipulieren, müssen sofort Alarme auslösen.",
      descriptionEn: "Log data must be protected against tampering, deletion, and unauthorised access. Write-Once-Read-Many (WORM) storage or cryptographic hash chains must be used to ensure integrity. Access to log data must be restricted to authorised personnel. Changes to logging configuration must themselves be logged. Attempts to delete or tamper with logs must immediately trigger alerts.",
      reason: "Angreifer versuchen regelmäßig, ihre Spuren durch Manipulation oder Löschung von Protokollen zu verwischen. Integritätsschutz stellt sicher, dass Protokolle als Beweismittel verwendet werden können.",
      reasonEn: "Attackers regularly attempt to cover their tracks by manipulating or deleting logs. Integrity protection ensures logs can be used as evidence.",
      whenRequired: "Immer erforderlich, insbesondere für Systeme, die regulatorischen Aufbewahrungspflichten unterliegen.",
      whenRequiredEn: "Always required, especially for systems subject to regulatory retention requirements.",
      sources: ["ISO 27001:2022 A.8.15", "BSI IT-Grundschutz OPS.1.1.5", "NIST CSF 2.0 DE.CM", "PCI DSS 4.0 Req.10.3"] },

    { id: "p27-c06", title: "Aufbewahrungsfristen für Protokolldaten", titleEn: "Log Retention Periods",
      description: "Wir müssen Aufbewahrungsfristen für verschiedene Protokolltypen definieren. Sicherheitsrelevante Protokolle müssen mindestens 12 Monate online und 3 Jahre archiviert aufbewahrt werden. Authentifizierungsprotokolle gelten als sicherheitsrelevant (siehe p27-c01) und müssen ebenfalls mindestens 12 Monate online verfügbar sein. Datenschutzrelevante Protokolle unterliegen zusätzlich den DSGVO-Anforderungen. Die Löschung nach Ablauf der Fristen muss automatisiert und dokumentiert erfolgen.",
      descriptionEn: "We must define retention periods for different log types. Security-relevant logs must be retained online for at least 12 months and archived for 3 years. Authentication logs are classified as security-relevant (see p27-c01) and must likewise be available online for at least 12 months. Privacy-relevant logs are additionally subject to GDPR requirements. Deletion after expiry of retention periods must be automated and documented.",
      reason: "Zu kurze Aufbewahrung verhindert die Aufklärung von Vorfällen, die erst spät erkannt werden. Zu lange Aufbewahrung verstößt gegen Datenschutzgrundsätze und erhöht Speicherkosten.",
      reasonEn: "Retention that is too short prevents investigation of incidents detected late. Retention that is too long violates data protection principles and increases storage costs.",
      whenRequired: "Immer erforderlich als regulatorische und operative Notwendigkeit.",
      whenRequiredEn: "Always required as a regulatory and operational necessity.",
      sources: ["ISO 27001:2022 A.8.15", "DSGVO Art.5(1)(e)", "BSI IT-Grundschutz OPS.1.1.5", "NIS2 Art.21(2)(i)"] },

    { id: "p27-c07", title: "Protokollierung von Cloud-Diensten", titleEn: "Cloud Service Logging",
      description: "Für alle genutzten Cloud-Dienste (IaaS, PaaS, SaaS) müssen die nativen Protokollierungsfunktionen aktiviert und in die zentrale Protokollinfrastruktur integriert werden. Cloud-Trail/Activity-Logs, IAM-Ereignisse, Konfigurationsänderungen und Daten-Zugriffsprotokolle müssen erfasst werden. Verträge mit Cloud-Anbietern müssen sicherstellen, dass ausreichende Protokolldaten bereitgestellt werden.",
      descriptionEn: "For all cloud services used (IaaS, PaaS, SaaS), native logging capabilities must be activated and integrated into central logging infrastructure. Cloud trail/activity logs, IAM events, configuration changes, and data access logs must be captured. Contracts with cloud providers must ensure sufficient log data is provided.",
      reason: "Cloud-Dienste generieren eigene Protokolle, die oft nicht automatisch in die zentrale Infrastruktur fließen. Ohne Integration bleiben Cloud-spezifische Vorfälle unentdeckt.",
      reasonEn: "Cloud services generate their own logs that often do not automatically flow into central infrastructure. Without integration, cloud-specific incidents remain undetected.",
      whenRequired: "Erforderlich für alle Organisationen, die Cloud-Dienste nutzen.",
      whenRequiredEn: "Required for all organisations using cloud services.",
      sources: ["ISO 27001:2022 A.8.15", "BSI C5:2020", "CSA CCM 4.0 LOG", "NIST CSF 2.0 DE.CM"] },

    { id: "p27-c08", title: "Anwendungs-Protokollierung (Application Logging)", titleEn: "Application Logging",
      description: "Geschäftskritische Anwendungen müssen sicherheitsrelevante Ereignisse protokollieren, einschließlich: Benutzeranmeldungen, Berechtigungsänderungen, Zugriffe auf sensible Datensätze, Transaktionen mit finanzieller Relevanz, Fehler und Ausnahmen sowie API-Aufrufe. Die Anwendungsprotokolle müssen im standardisierten Format erstellt und an die zentrale Infrastruktur weitergeleitet werden.",
      descriptionEn: "Business-critical applications must log security-relevant events, including: user logins, permission changes, access to sensitive records, financially relevant transactions, errors and exceptions, and API calls. Application logs must be created in standardised format and forwarded to central infrastructure.",
      reason: "Viele Angriffe zielen auf die Anwendungsschicht ab und sind nur in Anwendungsprotokollen sichtbar. Ohne Application Logging fehlt eine wesentliche Erkennungsebene.",
      reasonEn: "Many attacks target the application layer and are only visible in application logs. Without application logging, an essential detection layer is missing.",
      whenRequired: "Erforderlich für alle geschäftskritischen und kundenseitigen Anwendungen.",
      whenRequiredEn: "Required for all business-critical and customer-facing applications.",
      sources: ["ISO 27001:2022 A.8.15", "OWASP Logging Guide", "BSI IT-Grundschutz APP.1", "NIST CSF 2.0 DE.CM"] },

    { id: "p27-c09", title: "Datenschutzkonforme Log-Architektur (Privacy by Design)", titleEn: "Privacy-Compliant Log Architecture (Privacy by Design)",
      description: "Die Protokollierungsarchitektur muss von Beginn an datenschutzkonform gestaltet werden (Privacy by Design). Technische Maßnahmen umfassen: automatische Pseudonymisierung personenbezogener Felder vor der Speicherung, Tokenisierung von IP-Adressen und Benutzerkennungen, rollenbasierte Sichtbarkeitssteuerung (Depseudonymisierung nur durch autorisiertes Personal mit Vier-Augen-Prinzip) und technische Durchsetzung der Datensparsamkeit in Log-Pipelines. Die Rechtsgrundlage für jede Log-Kategorie muss dokumentiert sein. Die operative DSGVO-Überprüfung und periodische Compliance-Audits der Protokollierung werden in p27-c19 geregelt.",
      descriptionEn: "The logging architecture must be designed privacy-compliant from the outset (Privacy by Design). Technical measures include: automatic pseudonymisation of personal fields before storage, tokenisation of IP addresses and user identifiers, role-based visibility controls (depseudonymisation only by authorised personnel with dual-control principle), and technical enforcement of data minimisation in log pipelines. The legal basis for each log category must be documented. Operational GDPR reviews and periodic compliance audits of logging are governed by p27-c19.",
      reason: "Ohne technische Privacy-by-Design-Maßnahmen in der Log-Architektur ist nachträgliche DSGVO-Konformität aufwändig und fehleranfällig. Frühzeitige Integration reduziert Risiken und Kosten.",
      reasonEn: "Without technical privacy-by-design measures in log architecture, retroactive GDPR compliance is expensive and error-prone. Early integration reduces risks and costs.",
      whenRequired: "Immer erforderlich bei der Gestaltung oder Umgestaltung der Protokollierungsinfrastruktur. Siehe p27-c19 für operative DSGVO-Überprüfungen.",
      whenRequiredEn: "Always required when designing or redesigning logging infrastructure. See p27-c19 for operational GDPR reviews.",
      sources: ["DSGVO Art.5(1)(c), Art.25, Art.32", "ISO 27001:2022 A.8.15", "BSI IT-Grundschutz CON.2"] },

    { id: "p27-c10", title: "Planmäßiges Protokollierungs-Audit (Scheduled Audit)", titleEn: "Scheduled Logging Audit",
      description: "Die Protokollierungsinfrastruktur muss in geplanten Intervallen (mindestens quartalsweise) durch manuelle oder teilautomatisierte Audits überprüft werden. Die Audits umfassen: Prüfung, ob alle definierten Protokollquellen aktiv sind, Stichproben-basierte Validierung der Protokollvollständigkeit und -korrektheit, Überprüfung der Einhaltung von Aufbewahrungsfristen und Identifikation von Protokollierungslücken. Ergebnisse müssen dokumentiert, Defizite behoben und Korrekturmaßnahmen nachverfolgt werden. Die kontinuierliche automatisierte Qualitätsüberwachung zwischen den Audits wird in p27-c18 geregelt.",
      descriptionEn: "The logging infrastructure must be reviewed through planned (at least quarterly) manual or semi-automated audits. Audits include: verification that all defined log sources are active, sample-based validation of log completeness and correctness, review of retention period compliance, and identification of logging gaps. Results must be documented, deficiencies remediated, and corrective measures tracked. Continuous automated quality monitoring between audits is governed by p27-c18.",
      reason: "Planmäßige Audits bieten eine umfassende, kontextbezogene Bewertung, die automatisierte Checks nicht ersetzen können — sie validieren die Gesamtwirksamkeit der Protokollierungsstrategie.",
      reasonEn: "Scheduled audits provide comprehensive, contextual assessment that automated checks cannot replace — they validate the overall effectiveness of the logging strategy.",
      whenRequired: "Erforderlich als Teil des kontinuierlichen Verbesserungsprozesses. Siehe p27-c18 für automatisierte Qualitätsüberwachung.",
      whenRequiredEn: "Required as part of the continuous improvement process. See p27-c18 for automated quality monitoring.",
      sources: ["ISO 27001:2022 §9.2", "BSI IT-Grundschutz OPS.1.1.5", "NIST CSF 2.0 DE.CM"] },

    { id: "p27-c11", title: "Kapazitätsplanung für Protokollspeicher", titleEn: "Log Storage Capacity Planning",
      description: "Wir müssen die Speicherkapazität für Protokolldaten proaktiv planen und überwachen. Wachstumsprognosen müssen auf Basis historischer Daten erstellt werden. Schwellenwerte für Speicherauslastung müssen definiert werden (Warnung bei 70%, Alarm bei 85%). Automatische Skalierungsmechanismen oder geplante Erweiterungen müssen implementiert sein, um Datenverlust durch Speicherengpässe zu verhindern.",
      descriptionEn: "We must proactively plan and monitor storage capacity for log data. Growth projections must be based on historical data. Thresholds for storage utilisation must be defined (warning at 70%, alarm at 85%). Automatic scaling mechanisms or planned expansions must be implemented to prevent data loss through storage shortages.",
      reason: "Unzureichende Speicherkapazität führt zum Verlust aktueller Protokolldaten und damit zu blinden Flecken in der Sicherheitsüberwachung.",
      reasonEn: "Insufficient storage capacity leads to loss of current log data and thus to blind spots in security monitoring.",
      whenRequired: "Erforderlich für alle Organisationen mit zentraler Protokollinfrastruktur.",
      whenRequiredEn: "Required for all organisations with central logging infrastructure.",
      sources: ["ISO 27001:2022 A.8.6", "BSI IT-Grundschutz OPS.1.1.5", "NIST CSF 2.0 DE.CM"] },

    { id: "p27-c12", title: "Überprüfung und Aktualisierung der Protokollierungsrichtlinie", titleEn: "Review & Update of Logging Policy",
      description: "Diese Richtlinie muss mindestens jährlich überprüft und bei Bedarf aktualisiert werden. Anlässe für eine außerplanmäßige Überprüfung umfassen die Einführung neuer Systeme, Änderungen an Regulierungen, Erkenntnisse aus Sicherheitsvorfällen und Audit-Findings. Änderungen müssen von der verantwortlichen Stelle genehmigt und allen relevanten Parteien kommuniziert werden.",
      descriptionEn: "This policy must be reviewed at least annually and updated as needed. Triggers for unscheduled review include introduction of new systems, changes in regulations, lessons from security incidents, and audit findings. Changes must be approved by the responsible authority and communicated to all relevant parties.",
      reason: "Protokollierungsanforderungen ändern sich mit neuen Systemen, Regulierungen und Bedrohungen. Regelmäßige Überprüfung stellt sicher, dass die Richtlinie aktuell und wirksam bleibt.",
      reasonEn: "Logging requirements change with new systems, regulations, and threats. Regular review ensures the policy remains current and effective.",
      whenRequired: "Immer erforderlich als Teil des ISMS-Regelkreises.",
      whenRequiredEn: "Always required as part of the ISMS cycle.",
      sources: ["ISO 27001:2022 §10.1-10.2", "BSI IT-Grundschutz ISMS.1", "NIST CSF 2.0 GV.OC"] },
    { id: "p27-c13", title: "Cloud Shared-Responsibility-Modell für Protokollierung", titleEn: "Cloud Shared Responsibility Model for Logging", description: "Wir müssen das Shared-Responsibility-Modell für die Protokollierung jedes Cloud-Dienstes dokumentieren. Für jeden Dienst (IaaS, PaaS, SaaS) muss klar definiert sein, welche Log-Kategorien vom Cloud-Anbieter bereitgestellt werden und welche die Organisation selbst konfigurieren muss. Verantwortlichkeiten für Log-Erfassung, -Aufbewahrung und -Zugriff müssen vertraglich verankert sein. Die technische Integration von Cloud-Logs in die zentrale Infrastruktur wird in p27-c07 geregelt.", descriptionEn: "We must document the shared responsibility model for logging of each cloud service. For each service (IaaS, PaaS, SaaS), it must be clearly defined which log categories are provided by the cloud provider and which we must configure itself. Responsibilities for log collection, retention, and access must be contractually established. Technical integration of cloud logs into central infrastructure is governed by p27-c07.", reason: "Ohne klare Verantwortungszuordnung entstehen Lücken in der Cloud-Protokollierung, die bei Vorfällen kritisch werden.", reasonEn: "Without clear responsibility assignment, gaps in cloud logging arise that become critical during incidents.", whenRequired: "Erforderlich für alle Cloud-Dienste. Siehe p27-c07 für technische Cloud-Log-Integration.", whenRequiredEn: "Required for all cloud services. See p27-c07 for technical cloud log integration.", sources: ["ISO 27001:2022 A.5.23, A.8.15", "BSI C5:2020", "NIST CSF 2.0 DE.AE"] },
    { id: "p27-c14", title: "Log-Korrelation und Analyse — Datenanforderungen", titleEn: "Log Correlation & Analysis — Data Requirements", description: "Diese Klausel regelt die datenseitigen Anforderungen für die Log-Korrelation: Logs aus verschiedenen Quellen müssen normalisiert, mit einheitlichen Taxonomien versehen und korrelierbar gemacht werden. Korrelationsrelevante Felder (Zeitstempel, Benutzer-ID, Quell-IP, Ziel-System) müssen in allen Log-Formaten vorhanden sein. Die SIEM-seitige Implementierung der Korrelationsregeln, Use Cases und Alarmierung wird in p28 (SIEM Policy) geregelt.", descriptionEn: "This clause governs data-side requirements for log correlation: logs from different sources must be normalised, tagged with unified taxonomies, and made correlatable. Correlation-relevant fields (timestamp, user ID, source IP, target system) must be present in all log formats. SIEM-side implementation of correlation rules, use cases, and alerting is governed by p28 (SIEM Policy).", reason: "Ohne einheitliche Datenanforderungen kann keine effektive Korrelation erfolgen — die Datenqualität bestimmt die Erkennungsqualität.", reasonEn: "Without unified data requirements, no effective correlation can occur — data quality determines detection quality.", whenRequired: "Erforderlich für alle Organisationen mit mehreren Log-Quellen. Siehe p28 für SIEM-Korrelationsregeln.", whenRequiredEn: "Required for all organisations with multiple log sources. See p28 for SIEM correlation rules.", sources: ["ISO 27001:2022 A.8.16", "BSI IT-Grundschutz DER.1", "NIST CSF 2.0 DE.AE"] },
    { id: "p27-c15", title: "Forensische Sicherstellung von Logs", titleEn: "Forensic Preservation of Logs", description: "Bei Sicherheitsvorfällen müssen relevante Logs forensisch gesichert werden. Gesicherte Logs müssen unveränderbar, mit Zeitstempel versehen und in einer separaten Umgebung gespeichert werden. Chain-of-Custody-Dokumentation ist erforderlich.", descriptionEn: "During security incidents, relevant logs must be forensically preserved. Preserved logs must be immutable, timestamped, and stored in a separate environment. Chain-of-custody documentation is required.", reason: "Forensisch einwandfreie Logs sind für Vorfalluntersuchungen und rechtliche Verfahren essentiell.", reasonEn: "Forensically sound logs are essential for incident investigations and legal proceedings.", whenRequired: "Erforderlich bei allen Sicherheitsvorfällen.", whenRequiredEn: "Required for all security incidents.", sources: ["ISO 27001:2022 A.5.28", "BSI IT-Grundschutz DER.2.2", "NIST CSF 2.0 RS.AN"] },
    { id: "p27-c16", title: "Privilegierte Aktivitäten-Protokollierung", titleEn: "Privileged Activity Logging", description: "Alle Aktivitäten privilegierter Benutzer (Administratoren, Root-Zugriffe) müssen lückenlos protokolliert werden. Privileged Access Monitoring (PAM) muss Session-Recording, Keystroke-Logging und Command-Logging umfassen.", descriptionEn: "All activities of privileged users (administrators, root access) must be comprehensively logged. Privileged Access Monitoring (PAM) must include session recording, keystroke logging, and command logging.", reason: "Privilegierte Accounts haben den größten Schadensumfang. Lückenlose Protokollierung ist essentiell.", reasonEn: "Privileged accounts have the greatest damage potential. Comprehensive logging is essential.", whenRequired: "Erforderlich für alle privilegierten Zugänge.", whenRequiredEn: "Required for all privileged access.", sources: ["ISO 27001:2022 A.8.15, A.8.18", "BSI IT-Grundschutz OPS.1.1.5", "NIST CSF 2.0 DE.CM-03"] },
    { id: "p27-c17", title: "Netzwerk-Flow-Protokollierung", titleEn: "Network Flow Logging", description: "Netzwerk-Flow-Daten (NetFlow, sFlow, IPFIX) müssen erfasst und analysiert werden. Flow-Daten ermöglichen die Erkennung von Datenexfiltration, C2-Kommunikation und lateraler Bewegung. Baseline-Profile für normalen Datenverkehr müssen erstellt werden.", descriptionEn: "Network flow data (NetFlow, sFlow, IPFIX) must be captured and analysed. Flow data enables detection of data exfiltration, C2 communication, and lateral movement. Baseline profiles for normal traffic must be established.", reason: "Flow-Daten ergänzen Paket-basierte Analyse und ermöglichen Erkennung von Anomalien im Netzwerkverkehr.", reasonEn: "Flow data complements packet-based analysis and enables detection of network traffic anomalies.", whenRequired: "Empfohlen für alle Netzwerkumgebungen.", whenRequiredEn: "Recommended for all network environments.", sources: ["ISO 27001:2022 A.8.16", "BSI IT-Grundschutz NET.1.2", "NIST CSF 2.0 DE.CM"] },
    { id: "p27-c18", title: "Kontinuierliche automatisierte Log-Qualitätsüberwachung", titleEn: "Continuous Automated Log Quality Monitoring", description: "Zwischen den planmäßigen Audits (p27-c10) muss eine kontinuierliche automatisierte Überwachung der Log-Qualität erfolgen. Automatisierte Prüfungen umfassen: Erkennung fehlender oder ausgefallener Log-Quellen in Echtzeit, Identifikation von Log-Formatfehlern und Parsing-Problemen, Aufdeckung von Zeitstempel-Inkonsistenzen und Meldung von Log-Volumen-Anomalien (plötzlicher Anstieg oder Abfall). Automatisierte Alarme müssen bei Unterschreitung definierter Qualitätsschwellen ausgelöst werden.", descriptionEn: "Between scheduled audits (p27-c10), continuous automated monitoring of log quality must occur. Automated checks include: real-time detection of missing or failed log sources, identification of log format errors and parsing issues, discovery of timestamp inconsistencies, and reporting of log volume anomalies (sudden increase or decrease). Automated alerts must be triggered when defined quality thresholds are breached.", reason: "Automatisierte Überwachung schließt die Lücke zwischen planmäßigen Audits und erkennt Log-Ausfälle sofort, statt erst beim nächsten Audit.", reasonEn: "Automated monitoring bridges the gap between scheduled audits and detects log failures immediately rather than at the next audit.", whenRequired: "Empfohlen für alle zentralen Log-Systeme. Ergänzt die planmäßigen Audits in p27-c10.", whenRequiredEn: "Recommended for all centralised log systems. Complements scheduled audits in p27-c10.", sources: ["ISO 27001:2022 A.8.15", "BSI IT-Grundschutz OPS.1.1.5", "NIST CSF 2.0 DE.CM"] },
    { id: "p27-c19", title: "Operative DSGVO-Überprüfung der Protokollierung", titleEn: "Operational GDPR Review of Logging", description: "Wir müssen periodische (mindestens halbjährliche) operative Überprüfungen der DSGVO-Konformität der Protokollierung durchführen. Die Überprüfung umfasst: Validierung der in p27-c09 definierten Privacy-by-Design-Maßnahmen, Kontrolle der tatsächlichen Pseudonymisierungsraten, Überprüfung der Zugriffsprotokolle auf Log-Daten mit personenbezogenem Inhalt, Bewertung neuer Protokollquellen auf Datenschutzrelevanz und Abstimmung mit dem Datenschutzbeauftragten. Erkenntnisse müssen in die Weiterentwicklung der Log-Architektur (p27-c09) einfließen.", descriptionEn: "We must conduct periodic (at least semi-annual) operational reviews of GDPR compliance of logging. Reviews include: validation of privacy-by-design measures defined in p27-c09, control of actual pseudonymisation rates, review of access logs for log data containing personal content, assessment of new log sources for data protection relevance, and coordination with the Data Protection Officer. Findings must feed into further development of log architecture (p27-c09).", reason: "Technische Privacy-by-Design-Maßnahmen allein reichen nicht — regelmäßige operative Überprüfung stellt sicher, dass die Maßnahmen in der Praxis wirksam sind.", reasonEn: "Technical privacy-by-design measures alone are insufficient — regular operational review ensures measures are effective in practice.", whenRequired: "Erforderlich bei Protokollierung personenbezogener Daten. Siehe p27-c09 für technische Log-Architektur.", whenRequiredEn: "Required when logging personal data. See p27-c09 for technical log architecture.", sources: ["DSGVO Art.5, Art.6", "ISO 27001:2022 A.5.34", "BSI IT-Grundschutz OPS.1.1.5"] },
    { id: "p27-c20", title: "Log-basierte Alarmierung — Datenqualitätsanforderungen", titleEn: "Log-Based Alerting — Data Quality Requirements", description: "Log-Daten müssen die Mindestqualitätsanforderungen für eine zuverlässige Alarmierung erfüllen: vollständige Pflichtfelder, korrekte Zeitstempel, konsistente Schweregrad-Kennzeichnung und ausreichende Kontextinformationen. Log-basierte Alarmregeln müssen so gestaltet sein, dass sie die in p26-c04 definierten Alarm-Schweregrade und Reaktionszeiten unterstützen. Die operative Alarm-Priorisierung, Eskalation und Alert-Fatigue-Vermeidung werden in p26-c04 (Alarmmanagement) geregelt.", descriptionEn: "Log data must meet minimum quality requirements for reliable alerting: complete mandatory fields, correct timestamps, consistent severity tagging, and sufficient context information. Log-based alert rules must be designed to support the alert severities and response times defined in p26-c04. Operational alert prioritisation, escalation, and alert fatigue avoidance are governed by p26-c04 (Alert Management).", reason: "Die Qualität der Alarmierung hängt direkt von der Qualität der zugrunde liegenden Log-Daten ab — mangelhafte Logs erzeugen mangelhafte Alarme.", reasonEn: "Alert quality depends directly on the quality of underlying log data — poor logs produce poor alerts.", whenRequired: "Erforderlich für alle sicherheitsrelevanten Log-Quellen. Siehe p26-c04 für operatives Alarmmanagement.", whenRequiredEn: "Required for all security-relevant log sources. See p26-c04 for operational alert management.", sources: ["ISO 27001:2022 A.8.16", "BSI IT-Grundschutz DER.1", "NIST CSF 2.0 DE.AE"] },
    { id: "p27-c21", title: "IoC-Abgleich in Log-Daten — Datenanforderungen", titleEn: "IoC Matching in Log Data — Data Requirements", description: "Log-Daten müssen so strukturiert und indexiert sein, dass automatisierte Abgleiche mit Indicators of Compromise (IoC) effizient durchführbar sind. IP-Adressen, Domain-Namen, Datei-Hashes und URL-Muster müssen als durchsuchbare Felder in Logs vorhanden sein. Die Aufbewahrung muss retroaktive Abgleiche gegen neu identifizierte IoCs ermöglichen. Die strategische Threat-Intelligence-Integration, Feed-Management und Kontextualisierung werden in p26-c08 (Bedrohungsintelligenz) geregelt.", descriptionEn: "Log data must be structured and indexed so that automated matching with Indicators of Compromise (IoC) is efficiently feasible. IP addresses, domain names, file hashes, and URL patterns must be present as searchable fields in logs. Retention must enable retroactive matching against newly identified IoCs. Strategic threat intelligence integration, feed management, and contextualisation are governed by p26-c08 (Threat Intelligence).", reason: "IoC-Abgleiche sind nur so gut wie die Datenstruktur der Logs — ohne durchsuchbare Felder bleiben IoC-Treffer unentdeckt.", reasonEn: "IoC matching is only as good as the data structure of logs — without searchable fields, IoC hits remain undetected.", whenRequired: "Empfohlen für alle Organisationen. Siehe p26-c08 für strategische Threat-Intelligence-Integration.", whenRequiredEn: "Recommended for all organisations. See p26-c08 for strategic threat intelligence integration.", sources: ["ISO 27001:2022 A.5.7", "BSI IT-Grundschutz DER.1", "NIST CSF 2.0 DE.AE"] },
  ],

  // ═══════════════════════════════════════════════════════════════
  // P28 — Security Event Management (SIEM) Policy
  // Fokus: Technische SIEM-Plattform, Korrelationsregeln, Use Cases,
  //        SIEM-spezifische Performance/HA, Datenaufnahme und Analyse.
  // Abgrenzung: Log-Sammlung/-Qualität → p27, SOAR-Strategie → p26-c15,
  //             Threat-Intelligence-Strategie → p26-c08, Monitoring-Strategie → p29.
  // ═══════════════════════════════════════════════════════════════
  p28: [
    { id: "p28-c00", title: "Zweck und Umfang des Security Event Managements", titleEn: "Purpose & Scope of Security Event Management",
      description: "Wir müssen ein Security Information and Event Management (SIEM)-System betreiben oder nutzen, um sicherheitsrelevante Ereignisse aus verschiedenen Quellen zu sammeln, zu korrelieren und zu analysieren. Der Umfang muss alle kritischen Systeme, Netzwerkkomponenten, Sicherheitsinfrastruktur und Cloud-Dienste einschließen. Das SIEM-System ist die zentrale Plattform für die Sicherheitsüberwachung und Grundlage für die Incident-Detection. Die grundlegende Log-Sammlung, -Formatierung und -Qualität werden in p27 geregelt; diese Klausel fokussiert auf die SIEM-seitige Verarbeitung und Korrelation.",
      descriptionEn: "We must operate or use a Security Information and Event Management (SIEM) system to collect, correlate, and analyse security-relevant events from various sources. Scope must include all critical systems, network components, security infrastructure, and cloud services. The SIEM system is the central platform for security monitoring and the foundation for incident detection. Fundamental log collection, formatting, and quality are governed by p27; this clause focuses on SIEM-side processing and correlation.",
      reason: "Einzelne Protokollquellen liefern nur Fragmente des Gesamtbildes. Erst durch die Korrelation in einem SIEM werden komplexe Angriffsmuster erkennbar, die in Einzelprotokollen verborgen bleiben.",
      reasonEn: "Individual log sources provide only fragments of the overall picture. Only through correlation in a SIEM do complex attack patterns become visible that remain hidden in individual logs.",
      whenRequired: "Erforderlich für alle Organisationen mit komplexen IT-Umgebungen oder regulatorischen Überwachungsanforderungen.",
      whenRequiredEn: "Required for all organisations with complex IT environments or regulatory monitoring requirements.",
      sources: ["ISO 27001:2022 A.8.15-A.8.16", "NIS2 Art.21(2)(b)", "BSI IT-Grundschutz DER.1", "NIST CSF 2.0 DE.AE"] },

    { id: "p28-c01", title: "SIEM-Korrelationsregeln und Use Cases", titleEn: "SIEM Correlation Rules & Use Cases",
      description: "Wir müssen SIEM-Korrelationsregeln (Use Cases) für relevante Bedrohungsszenarien definieren und implementieren. Mindest-Use-Cases umfassen: Brute-Force-Angriffe, ungewöhnliche Anmeldezeiten, Privilege Escalation, Datenexfiltration, laterale Bewegung, Malware-Ausbreitung, ungewöhnliche DNS-Aktivität und Compliance-Verstöße. Use Cases müssen regelmäßig (mindestens vierteljährlich) überprüft und an die aktuelle Bedrohungslage angepasst werden. Die datenseitigen Korrelationsanforderungen (Feldnormalisierung, Taxonomien) werden in p27-c14 geregelt.",
      descriptionEn: "We must define and implement SIEM correlation rules (use cases) for relevant threat scenarios. Minimum use cases include: brute-force attacks, unusual login times, privilege escalation, data exfiltration, lateral movement, malware propagation, unusual DNS activity, and compliance violations. Use cases must be regularly reviewed (at least quarterly) and adapted to the current threat landscape. Data-side correlation requirements (field normalisation, taxonomies) are governed by p27-c14.",
      reason: "SIEM ohne spezifische Korrelationsregeln ist nur ein teures Log-Archiv. Nur durchdachte Use Cases ermöglichen die Erkennung relevanter Bedrohungen und reduzieren False Positives.",
      reasonEn: "SIEM without specific correlation rules is merely an expensive log archive. Only well-designed use cases enable detection of relevant threats and reduce false positives.",
      whenRequired: "Erforderlich sobald ein SIEM-System eingesetzt wird. Siehe p27-c14 für datenseitige Korrelationsanforderungen.",
      whenRequiredEn: "Required as soon as a SIEM system is deployed. See p27-c14 for data-side correlation requirements.",
      sources: ["ISO 27001:2022 A.8.16", "BSI IT-Grundschutz DER.1", "NIST CSF 2.0 DE.AE-02", "MITRE ATT&CK"] },

    { id: "p28-c02", title: "Ereigniskategorisierung und Schweregrad-Matrix", titleEn: "Event Categorisation & Severity Matrix",
      description: "Wir müssen eine standardisierte Ereigniskategorisierung und Schweregrad-Matrix für alle SIEM-generierten Alarme definieren. Schweregrade (z.B. P1-Kritisch bis P4-Informativ) müssen mit definierten Reaktionszeiten, Eskalationswegen und Verantwortlichkeiten verknüpft sein. Die Matrix muss mit dem Incident-Response-Prozess abgestimmt sein und alle relevanten Stakeholder müssen geschult sein. Die operative Alarm-Priorisierung und Alert-Fatigue-Vermeidung im SOC werden in p26-c04 geregelt.",
      descriptionEn: "We must define a standardised event categorisation and severity matrix for all SIEM-generated alerts. Severity levels (e.g., P1-Critical to P4-Informational) must be linked to defined response times, escalation paths, and responsibilities. The matrix must be aligned with the incident response process and all relevant stakeholders must be trained. Operational alert prioritisation and alert fatigue avoidance in the SOC are governed by p26-c04.",
      reason: "Ohne standardisierte Kategorisierung werden Ereignisse inkonsistent bewertet und kritische Alarme erhalten möglicherweise nicht die notwendige Aufmerksamkeit.",
      reasonEn: "Without standardised categorisation, events are assessed inconsistently and critical alerts may not receive the necessary attention.",
      whenRequired: "Erforderlich für alle SIEM-Implementierungen. Siehe p26-c04 für operatives Alarmmanagement.",
      whenRequiredEn: "Required for all SIEM implementations. See p26-c04 for operational alert management.",
      sources: ["ISO 27001:2022 A.5.25", "BSI IT-Grundschutz DER.2.1", "NIST CSF 2.0 DE.AE-02"] },

    { id: "p28-c03", title: "SIEM-Log-Quellen-Onboarding und Parser-Management", titleEn: "SIEM Log Source Onboarding & Parser Management",
      description: "Wir müssen einen strukturierten Prozess für das Onboarding neuer Log-Quellen speziell in das SIEM definieren. Für jede Quelle müssen SIEM-spezifische Parser, Normalisierungsregeln und Korrelationsmappings konfiguriert und getestet werden. Neue Systeme und Anwendungen müssen vor oder unmittelbar nach Produktivgang in das SIEM integriert werden. Ein SIEM-seitiges Inventar aller angebundenen und noch nicht angebundenen Quellen muss geführt und quartalsweise abgeglichen werden. Die grundlegende zentrale Log-Sammlung und -Aggregation (Transport, Pufferung, Verschlüsselung) wird in p27-c04 geregelt.",
      descriptionEn: "We must define a structured process for onboarding new log sources specifically into the SIEM. For each source, SIEM-specific parsers, normalisation rules, and correlation mappings must be configured and tested. New systems and applications must be integrated into SIEM before or immediately after going into production. A SIEM-side inventory of all connected and not-yet-connected sources must be maintained and reconciled quarterly. Fundamental central log collection and aggregation (transport, buffering, encryption) is governed by p27-c04.",
      reason: "Nicht angebundene Log-Quellen stellen blinde Flecken dar. Ein strukturierter SIEM-Onboarding-Prozess stellt sicher, dass Parser korrekt funktionieren und die SIEM-Abdeckung mit der IT-Landschaft Schritt hält.",
      reasonEn: "Unconnected log sources represent blind spots. A structured SIEM onboarding process ensures parsers function correctly and SIEM coverage keeps pace with the IT landscape.",
      whenRequired: "Erforderlich für alle SIEM-Implementierungen. Siehe p27-c04 für zentrale Log-Sammlung.",
      whenRequiredEn: "Required for all SIEM implementations. See p27-c04 for central log collection.",
      sources: ["ISO 27001:2022 A.8.15", "BSI IT-Grundschutz DER.1", "NIST CSF 2.0 DE.CM"] },

    { id: "p28-c04", title: "SIEM-Performance, Kapazität und Hochverfügbarkeit", titleEn: "SIEM Performance, Capacity & High Availability",
      description: "Die SIEM-Plattform muss hochverfügbar betrieben werden. Performance-Metriken wie Events per Second (EPS), Abfrage-Antwortzeiten und Korrelations-Latenz müssen überwacht werden. Die Plattform muss für Lastspitzen dimensioniert sein. Kapazitätsplanung muss Wachstum der Log-Volumina, neue Datenquellen und Performance-Anforderungen prognostizieren; Skalierungspläne müssen dokumentiert sein. Redundante Komponenten, automatisches Failover und regelmäßige DR-Tests müssen implementiert werden. Ein Ausfallkonzept muss sicherstellen, dass Protokolldaten auch bei SIEM-Ausfall zwischengespeichert und nach Wiederherstellung verarbeitet werden.",
      descriptionEn: "The SIEM platform must be operated with high availability. Performance metrics such as Events per Second (EPS), query response times, and correlation latency must be monitored. The platform must be sized for peak loads. Capacity planning must forecast growth of log volumes, new data sources, and performance requirements; scaling plans must be documented. Redundant components, automatic failover, and regular DR tests must be implemented. A failover concept must ensure log data is buffered during SIEM outage and processed after recovery.",
      reason: "Ein ausgefallenes oder überlastetes SIEM liefert keine Alarme und die Organisation ist während des Ausfalls blind für Angriffe. Proaktive Kapazitätsplanung verhindert Log-Verlust und Performance-Probleme.",
      reasonEn: "A failed or overloaded SIEM delivers no alerts and we are blind to attacks during the outage. Proactive capacity planning prevents log loss and performance problems.",
      whenRequired: "Erforderlich für alle produktiven SIEM-Deployments.",
      whenRequiredEn: "Required for all production SIEM deployments.",
      sources: ["ISO 27001:2022 A.8.6, A.8.14", "BSI IT-Grundschutz DER.1", "NIST CSF 2.0 DE.CM, PR.IR"] },

    { id: "p28-c05", title: "SIEM-Regeltuning und False-Positive-Management", titleEn: "SIEM Rule Tuning & False Positive Management",
      description: "SIEM-Korrelationsregeln müssen kontinuierlich optimiert werden, um die False-Positive-Rate zu senken, ohne die Erkennungsfähigkeit zu beeinträchtigen. Ein Tuning-Prozess muss etabliert werden, der regelmäßige Review-Zyklen, Feedback von Analysten, Whitelist-Management und die Dokumentation von Regeländerungen umfasst. Die False-Positive-Rate soll unter 30% gehalten werden.",
      descriptionEn: "SIEM correlation rules must be continuously optimised to reduce the false positive rate without compromising detection capability. A tuning process must be established that includes regular review cycles, analyst feedback, whitelist management, and documentation of rule changes. The false positive rate should be kept below 30%.",
      reason: "Zu viele Fehlalarme führen zu Alert Fatigue und dazu, dass echte Bedrohungen übersehen werden. Systematisches Tuning hält die Alarmqualität auf einem Niveau, das wirksame Reaktion ermöglicht.",
      reasonEn: "Too many false alarms lead to alert fatigue and result in real threats being overlooked. Systematic tuning maintains alert quality at a level that enables effective response.",
      whenRequired: "Erforderlich als kontinuierlicher Prozess für alle SIEM-Systeme.",
      whenRequiredEn: "Required as a continuous process for all SIEM systems.",
      sources: ["ISO 27001:2022 A.8.16", "BSI IT-Grundschutz DER.1", "NIST CSF 2.0 DE.AE"] },

    { id: "p28-c06", title: "Verhaltensanalyse und UEBA-Integration", titleEn: "Behavioural Analytics & UEBA Integration",
      description: "Wir sollen User and Entity Behaviour Analytics (UEBA)-Fähigkeiten implementieren und in das SIEM integrieren. UEBA erstellt Baseline-Profile für normales Verhalten von Benutzern, Systemen und Anwendungen und erkennt Abweichungen automatisch. Dies ergänzt regelbasierte Erkennung um die Fähigkeit, bisher unbekannte Bedrohungsmuster und Insider-Bedrohungen zu identifizieren. UEBA-Alarme müssen in die SIEM-Schweregrad-Matrix (p28-c02) eingebunden und über den regulären SOC-Prozess (p26-c13) bearbeitet werden. Die Integration umfasst: Baseline-Kalibrierung, Anomalie-Schwellenwerte, Kontextualisierung mit organisatorischen Rollen und periodische Modell-Validierung.",
      descriptionEn: "We should implement User and Entity Behaviour Analytics (UEBA) capabilities and integrate them into the SIEM. UEBA creates baseline profiles for normal behaviour of users, systems, and applications and automatically detects deviations. This supplements rule-based detection with the ability to identify previously unknown threat patterns and insider threats. UEBA alerts must be integrated into the SIEM severity matrix (p28-c02) and processed through the regular SOC process (p26-c13). Integration includes: baseline calibration, anomaly thresholds, contextualisation with organisational roles, and periodic model validation.",
      reason: "Regelbasierte Erkennung kann nur bekannte Muster finden. UEBA erkennt auch neuartige Angriffe und Insider-Bedrohungen, die keine bekannte Signatur aufweisen.",
      reasonEn: "Rule-based detection can only find known patterns. UEBA also detects novel attacks and insider threats that have no known signature.",
      whenRequired: "Empfohlen für Organisationen mit hohem Schutzbedarf und fortgeschrittenen Bedrohungsszenarien.",
      whenRequiredEn: "Recommended for organisations with high protection needs and advanced threat scenarios.",
      sources: ["ISO 27001:2022 A.8.16", "BSI IT-Grundschutz DER.1", "NIST CSF 2.0 DE.AE-02"] },

    { id: "p28-c07", title: "SIEM-Reporting, Dashboards und Compliance-Berichte", titleEn: "SIEM Reporting, Dashboards & Compliance Reports",
      description: "Das SIEM-System muss Dashboards und regelmäßige Berichte für verschiedene Zielgruppen bereitstellen. Operative Dashboards für SOC-Analysten müssen Echtzeit-Alarme und Trends zeigen. Management-Berichte müssen monatlich KPIs, Bedrohungstrends und Verbesserungsempfehlungen zusammenfassen. Compliance-relevante Berichte (Zugriffsprotokolle für Audits, NIS2-Vorfallmeldungen, DSGVO-Zugriffsnachweise, Verfügbarkeitsberichte) müssen automatisiert generiert werden können. Report-Templates müssen vordefiniert und anpassbar sein. Die strategische Berichterstattung an die Leitung wird in p29-c12 geregelt.",
      descriptionEn: "The SIEM system must provide dashboards and regular reports for various audiences. Operational dashboards for SOC analysts must show real-time alerts and trends. Management reports must monthly summarise KPIs, threat trends, and improvement recommendations. Compliance-relevant reports (access logs for audits, NIS2 incident reports, GDPR access records, availability reports) must be capable of automated generation. Report templates must be predefined and customisable. Strategic reporting to management is governed by p29-c12.",
      reason: "Ohne strukturiertes Reporting bleibt der Wert der Sicherheitsüberwachung für die Leitung unsichtbar. Automatisierte Compliance-Berichte reduzieren den manuellen Aufwand und die Fehleranfälligkeit.",
      reasonEn: "Without structured reporting, the value of security monitoring remains invisible to management. Automated compliance reports reduce manual effort and error-proneness.",
      whenRequired: "Erforderlich für alle SIEM-Implementierungen. Siehe p29-c12 für strategische Management-Berichterstattung.",
      whenRequiredEn: "Required for all SIEM implementations. See p29-c12 for strategic management reporting.",
      sources: ["ISO 27001:2022 §9.1, §9.3", "NIS2 Art.23", "DSGVO Art.30", "BSI IT-Grundschutz DER.1", "NIST CSF 2.0 DE.AE"] },

    { id: "p28-c08", title: "Forensische Datenhaltung und Analyse im SIEM", titleEn: "Forensic Data Retention & Analysis in SIEM",
      description: "Das SIEM muss forensische Analysen unterstützen, indem Rohdaten (nicht nur normalisierte Ereignisse) für definierte Zeiträume aufbewahrt werden. Analysten müssen in der Lage sein, historische Suchen durchzuführen, Zeitlinien zu rekonstruieren und Angriffspfade nachzuvollziehen. Forensische Werkzeuge und Abfragen müssen dokumentiert und regelmäßig getestet werden. Die forensische Sicherstellung von Logs bei Vorfällen wird in p27-c15 geregelt.",
      descriptionEn: "The SIEM must support forensic analyses by retaining raw data (not just normalised events) for defined periods. Analysts must be able to perform historical searches, reconstruct timelines, and trace attack paths. Forensic tools and queries must be documented and regularly tested. Forensic preservation of logs during incidents is governed by p27-c15.",
      reason: "Forensische Analysen sind entscheidend für die Aufklärung von Sicherheitsvorfällen und die Identifizierung des Ausmaßes einer Kompromittierung. Ohne Rohdatenhaltung sind tiefgehende Analysen unmöglich.",
      reasonEn: "Forensic analyses are crucial for investigating security incidents and identifying the scope of a compromise. Without raw data retention, deep analyses are impossible.",
      whenRequired: "Erforderlich für alle Organisationen, die Sicherheitsvorfälle forensisch aufklären müssen. Siehe p27-c15 für forensische Log-Sicherstellung.",
      whenRequiredEn: "Required for all organisations that must forensically investigate security incidents. See p27-c15 for forensic log preservation.",
      sources: ["ISO 27001:2022 A.5.28", "BSI IT-Grundschutz DER.2.2", "NIST CSF 2.0 RS.AN"] },

    { id: "p28-c09", title: "SIEM-Zugriffskontrolle und Rollen", titleEn: "SIEM Access Control & Roles",
      description: "Der Zugriff auf das SIEM-System muss rollenbasiert eingeschränkt werden. Mindestens folgende Rollen müssen definiert werden: Administrator (Konfiguration), Analyst (Ereignisanalyse, Suche), Viewer (nur lesend, für Management-Dashboards). Änderungen an SIEM-Konfigurationen und Regeln müssen einem Vier-Augen-Prinzip oder Change-Management-Prozess unterliegen. Der Zugriff muss selbst protokolliert werden.",
      descriptionEn: "Access to the SIEM system must be restricted on a role basis. At minimum, the following roles must be defined: Administrator (configuration), Analyst (event analysis, search), Viewer (read-only, for management dashboards). Changes to SIEM configurations and rules must be subject to a four-eyes principle or change management process. Access itself must be logged.",
      reason: "Unkontrollierter SIEM-Zugriff ermöglicht Manipulation von Überwachungsregeln und Alarmen. Rollenbasierte Kontrolle schützt die Integrität der Sicherheitsüberwachung.",
      reasonEn: "Uncontrolled SIEM access enables manipulation of monitoring rules and alerts. Role-based control protects the integrity of security monitoring.",
      whenRequired: "Erforderlich für alle SIEM-Implementierungen.",
      whenRequiredEn: "Required for all SIEM implementations.",
      sources: ["ISO 27001:2022 A.8.2-A.8.3", "BSI IT-Grundschutz DER.1", "NIST CSF 2.0 PR.AA"] },

    { id: "p28-c10", title: "Compliance-Monitoring über SIEM", titleEn: "Compliance Monitoring via SIEM",
      description: "Das SIEM muss Korrelationsregeln für die Überwachung der Einhaltung interner Richtlinien und externer Regulierungen enthalten. Dies umfasst die Erkennung von Richtlinienverstößen wie: unerlaubte Softwareinstallation, Zugriff außerhalb der Berechtigungen, Nichteinhaltung von Passwortrichtlinien, unverschlüsselte Datenübertragung und Zugriffe auf verbotene Websites. Compliance-Verletzungen müssen automatisch dokumentiert und an die zuständige Stelle eskaliert werden.",
      descriptionEn: "The SIEM must contain correlation rules for monitoring compliance with internal policies and external regulations. This includes detection of policy violations such as: unauthorised software installation, access outside permissions, non-compliance with password policies, unencrypted data transmission, and access to prohibited websites. Compliance violations must be automatically documented and escalated to the responsible authority.",
      reason: "Manuelle Compliance-Überwachung ist unzureichend und nicht skalierbar. Automatisierte SIEM-basierte Compliance-Erkennung stellt die kontinuierliche Einhaltung von Richtlinien sicher.",
      reasonEn: "Manual compliance monitoring is insufficient and not scalable. Automated SIEM-based compliance detection ensures continuous policy adherence.",
      whenRequired: "Erforderlich für Organisationen mit regulatorischen Compliance-Anforderungen.",
      whenRequiredEn: "Required for organisations with regulatory compliance requirements.",
      sources: ["ISO 27001:2022 A.5.36", "NIS2 Art.21", "BSI IT-Grundschutz ISMS.1", "NIST CSF 2.0 GV.OC"] },

    { id: "p28-c11", title: "Überprüfung der SIEM-Strategie und Roadmap", titleEn: "SIEM Strategy & Roadmap Review",
      description: "Die SIEM-Strategie und -Roadmap muss mindestens jährlich überprüft und aktualisiert werden. Dies umfasst die Bewertung der SIEM-Plattform gegen aktuelle Anforderungen, die Planung neuer Use Cases, die Integration neuer Datenquellen und die Evaluierung neuer Technologien (z.B. Cloud-SIEM, XDR). Investitions- und Ressourcenbedarfe müssen dokumentiert und der Leitung zur Entscheidung vorgelegt werden.",
      descriptionEn: "The SIEM strategy and roadmap must be reviewed and updated at least annually. This includes evaluation of the SIEM platform against current requirements, planning of new use cases, integration of new data sources, and evaluation of new technologies (e.g., cloud SIEM, XDR). Investment and resource needs must be documented and presented to management for decision.",
      reason: "Die Bedrohungslandschaft und IT-Infrastruktur entwickeln sich kontinuierlich. Ohne strategische Überprüfung verliert das SIEM an Relevanz und Wirksamkeit.",
      reasonEn: "The threat landscape and IT infrastructure evolve continuously. Without strategic review, the SIEM loses relevance and effectiveness.",
      whenRequired: "Erforderlich für alle Organisationen mit SIEM-Systemen.",
      whenRequiredEn: "Required for all organisations with SIEM systems.",
      sources: ["ISO 27001:2022 §10.1", "BSI IT-Grundschutz DER.1", "NIST CSF 2.0 GV.OC"] },

    { id: "p28-c12", title: "Cloud-SIEM und Hybrid-Architekturen", titleEn: "Cloud SIEM & Hybrid Architectures",
      description: "Cloud-basierte SIEM-Lösungen und Hybrid-Architekturen müssen bewertet und ggf. implementiert werden. Datenresidenz-Anforderungen müssen berücksichtigt werden. Die Integration von On-Premises- und Cloud-Log-Quellen muss nahtlos erfolgen. Die Cloud-Log-Integration auf Quellebene wird in p27-c07 geregelt; diese Klausel adressiert die SIEM-Plattform-Architektur selbst.",
      descriptionEn: "Cloud-based SIEM solutions and hybrid architectures must be evaluated and implemented if appropriate. Data residency requirements must be considered. Integration of on-premises and cloud log sources must be seamless. Cloud log integration at source level is governed by p27-c07; this clause addresses the SIEM platform architecture itself.",
      reason: "Cloud-SIEM bietet Skalierbarkeit und reduziert Infrastrukturkosten. Hybrid-Architekturen ermöglichen die Einhaltung von Datenresidenz-Anforderungen bei gleichzeitiger Cloud-Flexibilität.",
      reasonEn: "Cloud SIEM offers scalability and reduces infrastructure costs. Hybrid architectures enable compliance with data residency requirements while maintaining cloud flexibility.",
      whenRequired: "Empfohlen für Organisationen mit Cloud-Infrastruktur. Siehe p27-c07 für Cloud-Log-Integration.",
      whenRequiredEn: "Recommended for organisations with cloud infrastructure. See p27-c07 for cloud log integration.",
      sources: ["ISO 27001:2022 A.8.16", "BSI C5:2020", "NIST CSF 2.0 DE.AE"] },

    { id: "p28-c13", title: "SIEM-getriggerte Automatisierung (SOAR-Integration)", titleEn: "SIEM-Triggered Automation (SOAR Integration)",
      description: "Das SIEM muss SOAR-Integrationsschnittstellen bereitstellen, damit definierte Korrelationsergebnisse automatisch Playbooks auslösen können. Diese Klausel regelt die technische SIEM-seitige SOAR-Anbindung: API-Konnektoren, Trigger-Bedingungen, Datenübergabe-Formate und Rückmeldeschleifen (Playbook-Status zurück ins SIEM). Die strategische SOAR-Architektur, Playbook-Entwicklung und Governance der automatisierten Reaktion werden in p26-c15 geregelt.",
      descriptionEn: "The SIEM must provide SOAR integration interfaces so that defined correlation results can automatically trigger playbooks. This clause governs the technical SIEM-side SOAR integration: API connectors, trigger conditions, data handoff formats, and feedback loops (playbook status back to SIEM). Strategic SOAR architecture, playbook development, and governance of automated response are governed by p26-c15.",
      reason: "Ohne technisch saubere SIEM-SOAR-Schnittstellen können automatisierte Reaktionen nicht zuverlässig ausgelöst werden — die Integrationsqualität bestimmt die Automatisierungseffektivität.",
      reasonEn: "Without technically sound SIEM-SOAR interfaces, automated responses cannot be reliably triggered — integration quality determines automation effectiveness.",
      whenRequired: "Empfohlen für Organisationen mit SOAR-Implementierung. Siehe p26-c15 für strategische SOAR-Architektur.",
      whenRequiredEn: "Recommended for organisations with SOAR implementation. See p26-c15 for strategic SOAR architecture.",
      sources: ["ISO 27001:2022 A.5.26, A.8.16", "BSI IT-Grundschutz DER.2.1", "NIST CSF 2.0 RS.RP"] },

    { id: "p28-c14", title: "Threat-Intelligence-Feed-Ingestion im SIEM", titleEn: "Threat Intelligence Feed Ingestion in SIEM",
      description: "Das SIEM muss technische Schnittstellen für die automatisierte Aufnahme von Threat-Intelligence-Feeds bereitstellen. IoCs (IP-Adressen, Domains, File-Hashes) müssen automatisch gegen eingehende und historische Log-Daten abgeglichen werden. SIEM-seitige Feed-Konfiguration umfasst: Format-Unterstützung (STIX/TAXII, CSV, JSON), Aktualisierungsintervalle, Priorisierung nach Feed-Qualität und automatische Ablaufsteuerung (Aging/Expiry). Die strategische Threat-Intelligence-Beschaffung, Feed-Auswahl, Kontextualisierung und ISAC-Kooperationen werden in p26-c08 geregelt.",
      descriptionEn: "The SIEM must provide technical interfaces for automated ingestion of threat intelligence feeds. IoCs (IP addresses, domains, file hashes) must be automatically matched against incoming and historical log data. SIEM-side feed configuration includes: format support (STIX/TAXII, CSV, JSON), update intervals, prioritisation by feed quality, and automatic lifecycle management (aging/expiry). Strategic threat intelligence procurement, feed selection, contextualisation, and ISAC cooperations are governed by p26-c08.",
      reason: "Threat Intelligence erhöht die Erkennungsrate für bekannte Bedrohungen erheblich — aber nur wenn die SIEM-seitige Ingestion technisch korrekt und performant konfiguriert ist.",
      reasonEn: "Threat intelligence significantly increases detection rates for known threats — but only when SIEM-side ingestion is technically correctly and performantly configured.",
      whenRequired: "Empfohlen für alle SIEM-Implementierungen. Siehe p26-c08 für strategische Threat-Intelligence-Integration.",
      whenRequiredEn: "Recommended for all SIEM implementations. See p26-c08 for strategic threat intelligence integration.",
      sources: ["ISO 27001:2022 A.5.7", "BSI IT-Grundschutz DER.1", "NIST CSF 2.0 DE.AE"] },

    { id: "p28-c15", title: "SIEM-spezifische Log-Aufbewahrung (Tiered Storage)", titleEn: "SIEM-Specific Log Retention (Tiered Storage)",
      description: "Log-Daten im SIEM müssen in einer gestuften Speicherarchitektur aufbewahrt werden: Hot Storage für aktive Analysen und Echtzeit-Korrelation (mindestens 90 Tage), Warm Storage für historische Suchen und Threat-Hunting (bis 1 Jahr), Cold Storage/Archivierung für Compliance und retroaktive IoC-Abgleiche (gemäß Compliance-Anforderungen). Die Übergänge zwischen Speicherstufen müssen automatisiert und die Daten in jeder Stufe durchsuchbar sein. Die organisationsweiten Aufbewahrungsfristen und DSGVO-konformen Löschpflichten werden in p27-c06 geregelt.",
      descriptionEn: "Log data in the SIEM must be retained in a tiered storage architecture: hot storage for active analysis and real-time correlation (minimum 90 days), warm storage for historical searches and threat hunting (up to 1 year), cold storage/archival for compliance and retroactive IoC matching (per compliance requirements). Transitions between storage tiers must be automated and data must be searchable at each tier. Organisation-wide retention periods and GDPR-compliant deletion requirements are governed by p27-c06.",
      reason: "Ohne gestufte Speicherung werden entweder forensisch relevante Daten zu früh gelöscht oder Hot-Storage-Kosten eskalieren. Tiered Storage optimiert Kosten und Verfügbarkeit.",
      reasonEn: "Without tiered storage, either forensically relevant data is deleted too early or hot storage costs escalate. Tiered storage optimises cost and availability.",
      whenRequired: "Erforderlich für alle SIEM-Systeme. Siehe p27-c06 für organisationsweite Aufbewahrungsfristen.",
      whenRequiredEn: "Required for all SIEM systems. See p27-c06 for organisation-wide retention periods.",
      sources: ["NIS2 Art.23", "ISO 27001:2022 A.8.15", "BSI IT-Grundschutz DER.1"] },

    { id: "p28-c16", title: "SIEM-Schulung und Kompetenzentwicklung", titleEn: "SIEM Training & Skill Development",
      description: "SIEM-Analysten müssen regelmäßig geschult werden: Plattform-spezifische Schulungen, Korrelationsregel-Entwicklung, Log-Analyse-Methoden und aktuelle Bedrohungsszenarien. Zertifizierungen müssen gefördert werden. Die übergreifende Personal- und Kompetenzplanung für die gesamte Sicherheitsüberwachung wird in p29-c03 geregelt.",
      descriptionEn: "SIEM analysts must be regularly trained: platform-specific training, correlation rule development, log analysis methods, and current threat scenarios. Certifications must be promoted. Overarching staffing and competency planning for the entire security monitoring function is governed by p29-c03.",
      reason: "SIEM-Effektivität hängt maßgeblich von der Kompetenz der Analysten ab. Plattform-spezifisches Wissen ist Voraussetzung für effektive Nutzung.",
      reasonEn: "SIEM effectiveness depends significantly on analyst competence. Platform-specific knowledge is a prerequisite for effective use.",
      whenRequired: "Erforderlich für alle SOC-/SIEM-Teams. Siehe p29-c03 für übergreifende Personalplanung.",
      whenRequiredEn: "Required for all SOC/SIEM teams. See p29-c03 for overarching staffing planning.",
      sources: ["ISO 27001:2022 A.6.3", "BSI IT-Grundschutz ORP.3", "NIST CSF 2.0 GV.RR"] },

    { id: "p28-c17", title: "SIEM-Datenqualität und Ingestion-Pipeline", titleEn: "SIEM Data Quality & Ingestion Pipeline",
      description: "Log-Daten müssen in der SIEM-Ingestion-Pipeline normalisiert werden: einheitliche Zeitstempel, standardisierte Feldnamen, konsistente Formate und Anreicherung mit Kontextinformationen (Asset-Inventar, Risikobewertung). Automatisierte Datenqualitäts-Checks in der Ingestion-Pipeline müssen Parser-Fehler, fehlende Pflichtfelder und Format-Inkonsistenzen erkennen. Parser müssen bei Quell-Änderungen zeitnah aktualisiert werden. Die quellseitigen Log-Datenanforderungen (Formate, Pflichtfelder, Korrelierbarkeit) werden in p27-c14 und p27-c02 geregelt.",
      descriptionEn: "Log data must be normalised in the SIEM ingestion pipeline: unified timestamps, standardised field names, consistent formats, and enrichment with context information (asset inventory, risk assessment). Automated data quality checks in the ingestion pipeline must detect parser errors, missing mandatory fields, and format inconsistencies. Parsers must be promptly updated when sources change. Source-side log data requirements (formats, mandatory fields, correlatability) are governed by p27-c14 and p27-c02.",
      reason: "Unnormalisierte Daten in der SIEM-Pipeline führen zu falschen Korrelationen, übersehenen Bedrohungen und ineffizienten Analysen.",
      reasonEn: "Non-normalised data in the SIEM pipeline leads to false correlations, missed threats, and inefficient analyses.",
      whenRequired: "Erforderlich für alle SIEM-Datenquellen. Siehe p27-c14/p27-c02 für quellseitige Datenanforderungen.",
      whenRequiredEn: "Required for all SIEM data sources. See p27-c14/p27-c02 for source-side data requirements.",
      sources: ["ISO 27001:2022 A.8.15", "BSI IT-Grundschutz DER.1", "NIST CSF 2.0 DE.AE"] },
  ],

  // ═══════════════════════════════════════════════════════════════
  // P29 — Security Monitoring Strategy Policy
  // Fokus: Strategische Planung, Reifegrad, Governance, Budget,
  //        Branchenanpassung und übergreifende Architekturentscheidungen.
  // Abgrenzung: Operative SOC-Organisation → p26-c13, SIEM-Technik → p28,
  //             EDR-Architektur → p17, Vuln-Management → p21,
  //             Darknet-Monitoring → p26-c21.
  // ═══════════════════════════════════════════════════════════════
  p29: [
    { id: "p29-c00", title: "Strategische Ziele der Sicherheitsüberwachung", titleEn: "Strategic Objectives of Security Monitoring",
      description: "Wir müssen übergeordnete strategische Ziele für die Sicherheitsüberwachung definieren, die mit den Geschäftszielen und der Risikostrategie abgestimmt sind. Strategische Ziele umfassen: Maximierung der Erkennungsrate, Minimierung der Reaktionszeit, Schutz kritischer Geschäftsprozesse, Nachweis regulatorischer Compliance und Unterstützung der Geschäftskontinuität. Die Ziele müssen messbar formuliert und jährlich überprüft werden.",
      descriptionEn: "We must define overarching strategic objectives for security monitoring aligned with business goals and risk strategy. Strategic objectives include: maximising detection rate, minimising response time, protecting critical business processes, demonstrating regulatory compliance, and supporting business continuity. Objectives must be measurably formulated and reviewed annually.",
      reason: "Ohne strategische Ausrichtung wird die Sicherheitsüberwachung reaktiv und ineffizient. Klare Ziele ermöglichen eine zielgerichtete Investition von Ressourcen.",
      reasonEn: "Without strategic alignment, security monitoring becomes reactive and inefficient. Clear objectives enable targeted investment of resources.",
      whenRequired: "Immer erforderlich als Leitlinie für alle Überwachungsaktivitäten.",
      whenRequiredEn: "Always required as a guideline for all monitoring activities.",
      sources: ["ISO 27001:2022 §5.2, §6.2", "NIS2 Art.21", "BSI-Standard 200-1", "NIST CSF 2.0 GV.OC"] },

    { id: "p29-c01", title: "Risikoorientierte Überwachungspriorisierung", titleEn: "Risk-Based Monitoring Prioritisation",
      description: "Die Tiefe und Intensität der Überwachung muss auf Basis der Risikobewertung priorisiert werden. Systeme mit hohem Risiko erfordern Echtzeitüberwachung mit niedrigen Alarmschwellenwerten, mittleres Risiko ermöglicht Near-Realtime-Überwachung, geringes Risiko kann durch periodische Prüfungen abgedeckt werden. Die Priorisierung muss regelmäßig anhand aktualisierter Risikobewertungen neu bewertet werden.",
      descriptionEn: "The depth and intensity of monitoring must be prioritised based on risk assessment. High-risk systems require real-time monitoring with low alarm thresholds, medium risk allows near-real-time monitoring, low risk can be covered through periodic checks. Prioritisation must be regularly reassessed based on updated risk assessments.",
      reason: "Nicht alle Systeme erfordern den gleichen Überwachungsaufwand. Risikoorientierung stellt sicher, dass die begrenzten Überwachungsressourcen dort eingesetzt werden, wo sie den größten Nutzen bringen.",
      reasonEn: "Not all systems require the same monitoring effort. Risk orientation ensures limited monitoring resources are deployed where they provide the greatest benefit.",
      whenRequired: "Erforderlich um eine effiziente und effektive Ressourcenallokation sicherzustellen.",
      whenRequiredEn: "Required to ensure efficient and effective resource allocation.",
      sources: ["ISO 27001:2022 §6.1", "BSI-Standard 200-3", "NIST CSF 2.0 GV.RM"] },

    { id: "p29-c02", title: "Technologie-Architektur und Tool-Auswahl", titleEn: "Technology Architecture & Tool Selection",
      description: "Wir müssen eine kohärente Technologie-Architektur für die Sicherheitsüberwachung definieren. Die Architektur muss die Integration von SIEM (p28), EDR (p17), NDR, SOAR (p26-c15), Vulnerability Scanning (p21) und Threat Intelligence (p26-c08) beschreiben. Tool-Auswahlkriterien müssen Skalierbarkeit, Integrationsfähigkeit, Automatisierungsgrad und Kosten-Nutzen-Verhältnis berücksichtigen. Vendor-Lock-in-Risiken müssen bewertet werden. Diese Klausel definiert die strategische Architektur; die technische Umsetzung erfolgt in den jeweiligen Fachpolitiken.",
      descriptionEn: "We must define a coherent technology architecture for security monitoring. The architecture must describe the integration of SIEM (p28), EDR (p17), NDR, SOAR (p26-c15), vulnerability scanning (p21), and threat intelligence (p26-c08). Tool selection criteria must consider scalability, integration capability, degree of automation, and cost-benefit ratio. Vendor lock-in risks must be assessed. This clause defines the strategic architecture; technical implementation is handled in the respective specialist policies.",
      reason: "Fragmentierte Sicherheitstools ohne klare Architektur schaffen Silos und Integrationsdefizite. Eine ganzheitliche Architektur maximiert die Erkennungsfähigkeit und minimiert operative Komplexität.",
      reasonEn: "Fragmented security tools without clear architecture create silos and integration deficits. A holistic architecture maximises detection capability and minimises operational complexity.",
      whenRequired: "Erforderlich bei der Planung oder Erweiterung der Überwachungsinfrastruktur.",
      whenRequiredEn: "Required when planning or expanding monitoring infrastructure.",
      sources: ["ISO 27001:2022 A.8.16", "BSI IT-Grundschutz DER.1", "NIST CSF 2.0 DE"] },

    { id: "p29-c03", title: "Personal- und Kompetenzplanung für Sicherheitsüberwachung", titleEn: "Staffing & Competency Planning for Security Monitoring",
      description: "Wir müssen den Personalbedarf für die gesamte Sicherheitsüberwachung basierend auf dem Überwachungsumfang, den Betriebszeiten und den Servicelevels strategisch planen. Erforderliche Kompetenzen umfassen SIEM-Administration, Threat Hunting, forensische Analyse, Incident Response und Bedrohungsintelligenz. Weiterbildungsprogramme und Zertifizierungen (z.B. GCIA, GCIH, OSCP) müssen gefördert werden. Personalengpässe müssen durch Automation oder externe Dienstleister kompensiert werden. Die operative SOC-Organisation (Tier-Modell, Schichtplanung, Eskalation) wird in p26-c13 geregelt; SIEM-spezifische Schulungen in p28-c16.",
      descriptionEn: "We must strategically plan staffing needs for the entire security monitoring function based on monitoring scope, operating hours, and service levels. Required competencies include SIEM administration, threat hunting, forensic analysis, incident response, and threat intelligence. Training programmes and certifications (e.g., GCIA, GCIH, OSCP) must be promoted. Staffing shortages must be compensated through automation or external service providers. Operational SOC organisation (tier model, shift planning, escalation) is governed by p26-c13; SIEM-specific training in p28-c16.",
      reason: "Technologie allein reicht nicht für wirksame Überwachung. Qualifiziertes Personal ist entscheidend für die Interpretation von Alarmen, Threat Hunting und die Reaktion auf komplexe Bedrohungen.",
      reasonEn: "Technology alone is not sufficient for effective monitoring. Qualified personnel are crucial for interpreting alerts, threat hunting, and responding to complex threats.",
      whenRequired: "Erforderlich für jede Organisation, die Sicherheitsüberwachung betreibt. Siehe p26-c13 für operative SOC-Organisation.",
      whenRequiredEn: "Required for every organisation performing security monitoring. See p26-c13 for operational SOC organisation.",
      sources: ["ISO 27001:2022 §7.1-7.2", "BSI IT-Grundschutz ORP.3", "NIST CSF 2.0 GV.RR"] },

    { id: "p29-c04", title: "Threat-Hunting-Strategie und -Programm", titleEn: "Threat Hunting Strategy & Programme",
      description: "Wir sollen ein proaktives Threat-Hunting-Programm implementieren, das über die reaktive Alarmbearbeitung hinausgeht. Threat Hunting basiert auf Hypothesen über mögliche Angriffsmuster und sucht aktiv nach Indikatoren in den vorhandenen Daten. Hunting-Hypothesen müssen auf aktueller Bedrohungsintelligenz (p26-c08), branchenspezifischen Risiken (p29-c11) und bekannten Angriffstechniken (z.B. MITRE ATT&CK) basieren. Ein strukturiertes Programm muss definiert werden: Hunting-Kadenz, Verantwortlichkeiten, Tooling-Anforderungen, Dokumentation und Feedback-Schleifen. Ergebnisse müssen in neue SIEM-Korrelationsregeln (p28-c01) überführt und die Erkennungsabdeckung (p29-c13) verbessern.",
      descriptionEn: "We should implement a proactive threat hunting programme beyond reactive alert handling. Threat hunting is based on hypotheses about possible attack patterns and actively searches for indicators in existing data. Hunting hypotheses must be based on current threat intelligence (p26-c08), sector-specific risks (p29-c11), and known attack techniques (e.g., MITRE ATT&CK). A structured programme must be defined: hunting cadence, responsibilities, tooling requirements, documentation, and feedback loops. Results must be translated into new SIEM correlation rules (p28-c01) and improve detection coverage (p29-c13).",
      reason: "Automatisierte Erkennung findet nur bekannte Muster. Threat Hunting ermöglicht die Aufdeckung fortgeschrittener Bedrohungen, die allen Erkennungsregeln entgangen sind.",
      reasonEn: "Automated detection only finds known patterns. Threat hunting enables the discovery of advanced threats that have evaded all detection rules.",
      whenRequired: "Empfohlen für Organisationen mit hohem Schutzbedarf oder kritischer Infrastruktur.",
      whenRequiredEn: "Recommended for organisations with high protection needs or critical infrastructure.",
      sources: ["ISO 27001:2022 A.5.7", "BSI IT-Grundschutz DER.1", "NIST CSF 2.0 DE.AE", "MITRE ATT&CK"] },

    { id: "p29-c05", title: "Reifegrad-Modell und Verbesserungsplan", titleEn: "Maturity Model & Improvement Plan",
      description: "Wir müssen den Reifegrad unserer Sicherheitsüberwachung anhand eines Reifegradmodells (z.B. SOC-CMM, CREST SOC) bewerten und einen Verbesserungsplan erstellen. Der Reifegrad muss in den Dimensionen Technologie, Prozesse, Personal und Governance bewertet werden. Ziel-Reifegrade müssen für einen 1-3-Jahreshorizont definiert werden. Fortschritte müssen halbjährlich gemessen und berichtet werden.",
      descriptionEn: "We must assess the maturity of our security monitoring using a maturity model (e.g., SOC-CMM, CREST SOC) and create an improvement plan. Maturity must be assessed across technology, processes, personnel, and governance dimensions. Target maturity levels must be defined for a 1-3 year horizon. Progress must be measured and reported semi-annually.",
      reason: "Ohne Reifegradmessung fehlt eine objektive Bewertung der Überwachungsfähigkeiten. Ein strukturierter Verbesserungsplan stellt sicher, dass Investitionen die größten Defizite adressieren.",
      reasonEn: "Without maturity measurement, an objective assessment of monitoring capabilities is missing. A structured improvement plan ensures investments address the greatest deficits.",
      whenRequired: "Empfohlen für alle Organisationen, die ihre Überwachungsfähigkeiten systematisch weiterentwickeln wollen.",
      whenRequiredEn: "Recommended for all organisations wanting to systematically develop their monitoring capabilities.",
      sources: ["ISO 27001:2022 §10.1", "BSI IT-Grundschutz ISMS.1", "NIST CSF 2.0 GV.OC", "SOC-CMM"] },

    { id: "p29-c06", title: "Multi-Cloud- und Hybrid-Überwachungsstrategie", titleEn: "Multi-Cloud & Hybrid Monitoring Strategy",
      description: "Organisationen mit Multi-Cloud- oder Hybrid-Infrastrukturen müssen eine einheitliche Überwachungsstrategie definieren, die alle Umgebungen (On-Premises, Public Cloud, Private Cloud, SaaS) konsistent abdeckt. Cloud-native Überwachungstools müssen mit der zentralen Plattform integriert werden. Visibilität darf nicht durch Cloud-Provider-Grenzen eingeschränkt werden. Die Strategie muss die spezifischen Herausforderungen jeder Plattform adressieren.",
      descriptionEn: "Organisations with multi-cloud or hybrid infrastructures must define a unified monitoring strategy consistently covering all environments (on-premises, public cloud, private cloud, SaaS). Cloud-native monitoring tools must be integrated with the central platform. Visibility must not be limited by cloud provider boundaries. The strategy must address the specific challenges of each platform.",
      reason: "Multi-Cloud-Umgebungen schaffen natürliche Silos in der Überwachung. Ohne einheitliche Strategie entstehen blinde Flecken zwischen den Umgebungen, die Angreifer ausnutzen können.",
      reasonEn: "Multi-cloud environments create natural silos in monitoring. Without a unified strategy, blind spots arise between environments that attackers can exploit.",
      whenRequired: "Erforderlich für Organisationen, die mehrere Cloud-Provider oder Hybrid-Infrastrukturen nutzen.",
      whenRequiredEn: "Required for organisations using multiple cloud providers or hybrid infrastructures.",
      sources: ["ISO 27001:2022 A.8.16", "BSI C5:2020", "CSA CCM 4.0", "NIST CSF 2.0 DE.CM"] },

    { id: "p29-c07", title: "Budget- und Ressourcenplanung für Sicherheitsüberwachung", titleEn: "Budget & Resource Planning for Security Monitoring",
      description: "Wir müssen ein dediziertes Budget für die Sicherheitsüberwachung bereitstellen, das Technologie-Lizenzen, Personal, Schulungen, externe Dienstleistungen und Infrastrukturkosten umfasst. Das Budget muss auf Basis des Risikoprofils und der Organisationsgröße angemessen sein. Kosten-Nutzen-Analysen für neue Investitionen müssen durchgeführt werden. Die Budgetplanung muss als Teil des jährlichen Planungsprozesses erfolgen.",
      descriptionEn: "We must provide a dedicated budget for security monitoring covering technology licences, personnel, training, external services, and infrastructure costs. The budget must be appropriate based on the risk profile and organisation size. Cost-benefit analyses for new investments must be performed. Budget planning must occur as part of the annual planning process.",
      reason: "Sicherheitsüberwachung ohne angemessenes Budget führt zu Lücken in Technologie und Personal. Transparente Budgetierung ermöglicht der Leitung fundierte Investitionsentscheidungen.",
      reasonEn: "Security monitoring without adequate budget leads to gaps in technology and personnel. Transparent budgeting enables management to make informed investment decisions.",
      whenRequired: "Erforderlich für alle Organisationen als Grundlage nachhaltiger Sicherheitsüberwachung.",
      whenRequiredEn: "Required for all organisations as the foundation of sustainable security monitoring.",
      sources: ["ISO 27001:2022 §7.1", "NIS2 Art.20(1)", "BSI-Standard 200-1", "NIST CSF 2.0 GV.RR"] },

    { id: "p29-c08", title: "Zusammenarbeit mit externen Stellen (CERTs, Behörden)", titleEn: "Cooperation with External Bodies (CERTs, Authorities)",
      description: "Wir müssen Prozesse für die Zusammenarbeit mit externen Sicherheitsstellen definieren, einschließlich nationaler und branchenspezifischer CERTs/CSIRTs, Aufsichtsbehörden (BSI, BaFin etc.) und ISAC/ISAO-Netzwerken. Kontaktdaten und Kommunikationsverfahren müssen dokumentiert und aktuell gehalten werden. Meldepflichten nach NIS2 müssen in die Überwachungsprozesse integriert werden. Der Austausch von Bedrohungsinformationen muss aktiv betrieben werden.",
      descriptionEn: "We must define processes for cooperation with external security bodies, including national and sector-specific CERTs/CSIRTs, supervisory authorities (BSI, BaFin, etc.), and ISAC/ISAO networks. Contact details and communication procedures must be documented and kept current. NIS2 reporting obligations must be integrated into monitoring processes. Exchange of threat information must be actively pursued.",
      reason: "Effektive Sicherheitsüberwachung erfordert den Austausch mit der Sicherheitsgemeinschaft. CERTs und ISACs liefern wertvolle Bedrohungsinformationen und unterstützen bei der Vorfallbearbeitung.",
      reasonEn: "Effective security monitoring requires exchange with the security community. CERTs and ISACs provide valuable threat information and support incident handling.",
      whenRequired: "Erforderlich insbesondere für NIS2-regulierte Organisationen und Betreiber kritischer Infrastrukturen.",
      whenRequiredEn: "Required especially for NIS2-regulated organisations and critical infrastructure operators.",
      sources: ["NIS2 Art.21(2)(b), Art.23", "BSI IT-Grundschutz DER.2.1", "NIST CSF 2.0 RS.CO"] },

    { id: "p29-c09", title: "Überprüfung der Überwachungsstrategie und -richtlinie", titleEn: "Monitoring Strategy & Policy Review",
      description: "Die Überwachungsstrategie und diese Richtlinie müssen mindestens jährlich oder bei wesentlichen Änderungen (neue Bedrohungen, organisatorische Umstrukturierung, Technologiewechsel, Sicherheitsvorfälle) überprüft werden. Die Überprüfung muss die Angemessenheit der strategischen Ziele, die Wirksamkeit der implementierten Maßnahmen, Ressourcenadäquanz, Lessons Learned aus Vorfällen und Verbesserungspotentiale bewerten. Neue Technologien und regulatorische Entwicklungen müssen berücksichtigt werden. Ergebnisse müssen der Leitung berichtet und Änderungen genehmigt, kommuniziert und dokumentiert werden.",
      descriptionEn: "The monitoring strategy and this policy must be reviewed at least annually or upon significant changes (new threats, organisational restructuring, technology changes, security incidents). The review must assess the adequacy of strategic objectives, effectiveness of implemented measures, resource adequacy, lessons learned from incidents, and improvement potential. New technologies and regulatory developments must be considered. Results must be reported to management and changes approved, communicated, and documented.",
      reason: "Strategien und Richtlinien veralten ohne regelmäßige Überprüfung. Die Bedrohungslandschaft, Technologien und regulatorische Anforderungen ändern sich kontinuierlich und erfordern strategische Anpassung.",
      reasonEn: "Strategies and policies become outdated without regular review. The threat landscape, technologies, and regulatory requirements change continuously and require strategic adaptation.",
      whenRequired: "Immer erforderlich als Teil des strategischen Managementprozesses.",
      whenRequiredEn: "Always required as part of the strategic management process.",
      sources: ["ISO 27001:2022 §9.3, §10.1-10.2", "BSI-Standard 200-1", "NIST CSF 2.0 GV.OC"] },

    { id: "p29-c10", title: "Zero-Trust-Monitoring-Prinzipien", titleEn: "Zero Trust Monitoring Principles",
      description: "Die Überwachungsstrategie muss Zero-Trust-Prinzipien berücksichtigen: Jede Transaktion muss verifiziert werden, Vertrauen wird nicht auf Basis des Netzwerkstandorts gewährt, und Mikrosegmentierung erfordert granulare Überwachung innerhalb und zwischen Segmenten. Die Überwachung muss auch den internen Ost-West-Verkehr abdecken und nicht nur den Nord-Süd-Verkehr an der Netzwerkgrenze.",
      descriptionEn: "The monitoring strategy must consider zero trust principles: every transaction must be verified, trust is not granted based on network location, and micro-segmentation requires granular monitoring within and between segments. Monitoring must also cover internal east-west traffic, not just north-south traffic at the network boundary.",
      reason: "Traditionelle perimeterbasierte Überwachung ist in modernen, verteilten Umgebungen unzureichend. Zero-Trust-Monitoring erkennt Bedrohungen auch innerhalb vertrauenswürdiger Netzwerkzonen.",
      reasonEn: "Traditional perimeter-based monitoring is insufficient in modern, distributed environments. Zero trust monitoring detects threats even within trusted network zones.",
      whenRequired: "Empfohlen für Organisationen, die eine Zero-Trust-Architektur implementieren oder planen.",
      whenRequiredEn: "Recommended for organisations implementing or planning a zero trust architecture.",
      sources: ["ISO 27001:2022 A.8.16", "NIST SP 800-207", "BSI IT-Grundschutz NET.1.1", "NIST CSF 2.0 PR.AA"] },

    { id: "p29-c11", title: "Anpassung an Branchenspezifische Bedrohungen", titleEn: "Adaptation to Sector-Specific Threats",
      description: "Die Überwachungsstrategie muss branchenspezifische Bedrohungen und Angriffsmuster berücksichtigen. Für den Gesundheitssektor sind z.B. Ransomware-spezifische Erkennungsregeln kritisch, für den Finanzsektor Betrugserkennungsmuster, für den Energiesektor OT-spezifische Anomalien. Die Anpassung muss auf Basis branchenspezifischer Bedrohungsintelligenz und ISAC-Informationen erfolgen. Sektorspezifische regulatorische Anforderungen müssen berücksichtigt werden.",
      descriptionEn: "The monitoring strategy must consider sector-specific threats and attack patterns. For the healthcare sector, ransomware-specific detection rules are critical; for the financial sector, fraud detection patterns; for the energy sector, OT-specific anomalies. Adaptation must be based on sector-specific threat intelligence and ISAC information. Sector-specific regulatory requirements must be considered.",
      reason: "Generische Überwachungsstrategien berücksichtigen nicht die spezifischen Risiken und Angriffsmuster der jeweiligen Branche. Branchenspezifische Anpassung erhöht die Erkennungseffektivität erheblich.",
      reasonEn: "Generic monitoring strategies do not account for the specific risks and attack patterns of the respective sector. Sector-specific adaptation significantly increases detection effectiveness.",
      whenRequired: "Erforderlich für NIS2-regulierte Organisationen in spezifischen Sektoren.",
      whenRequiredEn: "Required for NIS2-regulated organisations in specific sectors.",
      sources: ["NIS2 Art.21, Annex I/II", "BSI KRITIS-Verordnung", "NIST CSF 2.0 GV.SC"] },

    { id: "p29-c12", title: "Metriken und Berichterstattung an die Leitung", titleEn: "Metrics & Reporting to Management",
      description: "Wir müssen regelmäßig (mindestens vierteljährlich) der Leitung über den Status der Sicherheitsüberwachung berichten. Der Bericht muss KPIs (MTTD, MTTR, Abdeckungsgrad, Alarmtrends), bedeutende Erkennungen, Bedrohungstrends, Ressourcenstatus und Verbesserungsempfehlungen umfassen. Die Berichterstattung muss in einer für die Leitung verständlichen Form erfolgen und strategische Risiken adressieren. SIEM-operative Dashboards und Compliance-Berichte werden in p28-c07 erstellt.",
      descriptionEn: "We must regularly (at least quarterly) report to management on the status of security monitoring. The report must include KPIs (MTTD, MTTR, coverage ratio, alert trends), significant detections, threat trends, resource status, and improvement recommendations. Reporting must be in a form understandable to management and address strategic risks. SIEM operational dashboards and compliance reports are generated in p28-c07.",
      reason: "Die Leitung trägt nach NIS2 die Gesamtverantwortung für Cybersicherheit. Regelmäßige Berichterstattung stellt sicher, dass die Leitung informierte Entscheidungen treffen kann.",
      reasonEn: "Management bears overall responsibility for cybersecurity under NIS2. Regular reporting ensures management can make informed decisions.",
      whenRequired: "Immer erforderlich als NIS2-Anforderung und Best Practice. Siehe p28-c07 für SIEM-operative Berichte.",
      whenRequiredEn: "Always required as a NIS2 requirement and best practice. See p28-c07 for SIEM operational reports.",
      sources: ["NIS2 Art.20(1)", "ISO 27001:2022 §9.3", "BSI-Standard 200-1", "NIST CSF 2.0 GV.OC"] },

    { id: "p29-c13", title: "Erkennungs-Abdeckungsgrad und Schwachstellenintegration", titleEn: "Detection Coverage & Vulnerability Integration",
      description: "Der Abdeckungsgrad der Sicherheitsüberwachung muss gemessen und dokumentiert werden. MITRE ATT&CK Framework muss als Referenz für die Bewertung der Erkennungsfähigkeiten verwendet werden. Lücken müssen identifiziert und priorisiert geschlossen werden. Die Ergebnisse von Schwachstellen-Scans müssen strategisch in die Überwachungspriorisierung einfließen: Systeme mit bekannten kritischen Schwachstellen erfordern erhöhte Monitoring-Intensität bis zur Behebung. Das operative Vulnerability Scanning und Management (Scan-Durchführung, CVSS-Priorisierung, Remediation-Fristen) wird in p21 geregelt.",
      descriptionEn: "Security monitoring coverage must be measured and documented. MITRE ATT&CK framework must be used as reference for evaluating detection capabilities. Gaps must be identified and closed with priority. Vulnerability scan results must strategically feed into monitoring prioritisation: systems with known critical vulnerabilities require increased monitoring intensity until remediation. Operational vulnerability scanning and management (scan execution, CVSS prioritisation, remediation timelines) is governed by p21.",
      reason: "Ohne Messung des Abdeckungsgrads bleiben Erkennungslücken unbekannt. Die Integration von Schwachstelleninformationen in die Überwachungspriorisierung stellt sicher, dass verwundbare Systeme verstärkt beobachtet werden.",
      reasonEn: "Without measuring coverage, detection gaps remain unknown. Integration of vulnerability information into monitoring prioritisation ensures vulnerable systems receive enhanced observation.",
      whenRequired: "Empfohlen für alle Organisationen mit Sicherheitsüberwachung. Siehe p21 für operatives Vulnerability Management.",
      whenRequiredEn: "Recommended for all organisations with security monitoring. See p21 for operational vulnerability management.",
      sources: ["MITRE ATT&CK", "ISO 27001:2022 A.8.8, A.8.16", "NIS2 Art.21(2)(e)", "NIST CSF 2.0 DE.AE, DE.CM"] },

    { id: "p29-c14", title: "Strategische Endpunkt- und Netzwerkerkennung (EDR/NDR-Positionierung)", titleEn: "Strategic Endpoint & Network Detection (EDR/NDR Positioning)",
      description: "Die Überwachungsstrategie muss die strategische Rolle von Endpoint Detection & Response (EDR) und Network Detection & Response (NDR) im Gesamtökosystem definieren. EDR adressiert endpunktbasierte Bedrohungen (Malware, fileless attacks, Privilege Escalation), NDR adressiert netzwerkbasierte Bedrohungen (laterale Bewegung, C2-Kommunikation, Datenexfiltration). Die Strategie muss definieren, wie EDR- und NDR-Telemetrie in SIEM (p28) und SOC (p26-c13) zusammenfließen und sich gegenseitig ergänzen. Die technische EDR-Architektur und Compliance-Anforderungen an Endpunkte werden in p17 geregelt; die operative EDR-Telemetrie-Integration in p26-c09; die operative Netzwerkverkehrsüberwachung in p26-c02.",
      descriptionEn: "The monitoring strategy must define the strategic role of Endpoint Detection & Response (EDR) and Network Detection & Response (NDR) in the overall ecosystem. EDR addresses endpoint-based threats (malware, fileless attacks, privilege escalation), NDR addresses network-based threats (lateral movement, C2 communication, data exfiltration). The strategy must define how EDR and NDR telemetry flows into SIEM (p28) and SOC (p26-c13) and complements each other. Technical EDR architecture and endpoint compliance requirements are governed by p17; operational EDR telemetry integration in p26-c09; operational network traffic monitoring in p26-c02.",
      reason: "EDR und NDR sind komplementäre Erkennungsschichten. Ohne strategische Positionierung entstehen Überlappungen oder Lücken zwischen Endpunkt- und Netzwerkerkennung.",
      reasonEn: "EDR and NDR are complementary detection layers. Without strategic positioning, overlaps or gaps arise between endpoint and network detection.",
      whenRequired: "Erforderlich für Organisationen mit mehreren Erkennungsschichten. Siehe p17 für EDR-Technik, p26-c02/c09 für operative Integration.",
      whenRequiredEn: "Required for organisations with multiple detection layers. See p17 for EDR technology, p26-c02/c09 for operational integration.",
      sources: ["ISO 27001:2022 A.8.7, A.8.16, A.8.20", "BSI IT-Grundschutz SYS.2.1, NET.1.2", "NIST CSF 2.0 DE.CM"] },

    { id: "p29-c15", title: "Honeypots und Deception-Technologien", titleEn: "Honeypots & Deception Technologies",
      description: "Deception-Technologien (Honeypots, Honeytokens, Decoy-Systeme) sollten als strategische Erkennungsschicht eingesetzt werden, um Angreifer frühzeitig zu erkennen. Die Strategie muss definieren: Platzierung in kritischen Netzwerksegmenten, Art der Deception-Assets (Fake-Server, Fake-Credentials, Fake-Daten), Integration der Alarme in SIEM (p28) und SOC (p26-c13), sowie Wartung und Aktualisierung der Deception-Umgebung. Alarme bei Interaktion mit Decoy-Systemen müssen höchste Priorität haben, da sie per Definition verdächtig sind.",
      descriptionEn: "Deception technologies (honeypots, honeytokens, decoy systems) should be deployed as a strategic detection layer to detect attackers early. The strategy must define: placement in critical network segments, type of deception assets (fake servers, fake credentials, fake data), integration of alerts into SIEM (p28) and SOC (p26-c13), and maintenance and updating of the deception environment. Alerts upon interaction with decoy systems must have highest priority, as they are suspicious by definition.",
      reason: "Jede Interaktion mit einem Honeypot ist per Definition verdächtig und ein starker Indikator für einen Angriff. Deception-Technologien erkennen auch Bedrohungen, die alle anderen Schichten umgangen haben.",
      reasonEn: "Any interaction with a honeypot is suspicious by definition and a strong indicator of an attack. Deception technologies also detect threats that have bypassed all other layers.",
      whenRequired: "Empfohlen für Organisationen mit hohem Bedrohungsniveau.",
      whenRequiredEn: "Recommended for organisations with high threat level.",
      sources: ["ISO 27001:2022 A.8.16", "NIST CSF 2.0 DE.CM", "BSI IT-Grundschutz DER.1"] },
  ],
};
